#### **4. Production-Grade Secret Management Architecture**

**Option A: AWS Secrets Manager (Recommended for AWS)**
```javascript
// secrets/aws-secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class AWSSecrets {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, useCache = true) {
    if (useCache && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const response = await this.client.send(
        new GetSecretValueCommand({
          SecretId: secretName,
          VersionStage: 'AWSCURRENT',
        })
      );

      const secretValue = JSON.parse(response.SecretString);

      if (useCache) {
        this.cache.set(secretName, {
          value: secretValue,
          timestamp: Date.now(),
        });
      }

      return secretValue;
    } catch (error) {
      console.error(`Failed to fetch secret ${secretName}:`, error);
      throw error;
    }
  }
}

module.exports = new AWSSecrets();
```

