// app.js with secure secret loading
const express = require('express');
const helmet = require('helmet');
const crypto = require('crypto');
const secrets = require('./config/secrets');

async function bootstrapApp() {
  try {
    // Load secrets first
    await secrets.load();

    // Validate secrets are present
    const requiredSecrets = ['database.url', 'jwt.secret'];
    for (const secretPath of requiredSecrets) {
      if (!secrets.get(secretPath)) {
        throw new Error(`Missing required secret: ${secretPath}`);
      }
    }

    const app = express();

    // Generate session secret if not in production secrets
    const sessionSecret = process.env.NODE_ENV === 'production' 
      ? secrets.get('session.secret')
      : crypto.randomBytes(64).toString('hex');

    // Configure app with secrets
    app.set('session secret', sessionSecret);

    // Security middleware
    app.use(helmet());

    // Database connection using secrets
    const databaseConfig = {
      connectionString: secrets.get('database.url'),
      ssl: process.env.NODE_ENV === 'production' 
        ? { rejectUnauthorized: true }
        : false,
    };

    // API routes that use secrets
    app.get('/config/health', (req, res) => {
      // NEVER expose actual secrets in responses
      res.json({
        status: 'ok',
        environment: process.env.NODE_ENV,
        services: {
          database: secrets.get('database.url') ? 'configured' : 'missing',
          aws: secrets.get('aws.accessKeyId') ? 'configured' : 'missing',
        },
        // Only expose non-sensitive configuration
        features: {
          logging: !!secrets.get('logfire.token'),
          payments: !!secrets.get('apiKeys.stripe'),
        }
      });
    });

    return app;
  } catch (error) {
    console.error('Failed to bootstrap app:', error);
    process.exit(1);
  }
}

// Export the bootstrap function
module.exports = bootstrapApp;
```

