// Parse the rotation log and extract credentials
function parseCredentialsFromLog(logContent) {
  const lines = logContent.split('\n');
  const credentials = [];
  let currentCredential = null;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();

    // Look for credential sections
    if (line.startsWith('###')) {
      // This marks the start of a credential section like "### 1. DATABASE CONNECTION"
      // The actual credential details start after this
    }

    // Look for Variable lines
    if (line.startsWith('**Variable:** `')) {
      const variableMatch = line.match(/`([^`]+)`/);
      if (variableMatch) {
        currentCredential = {
          variable: variableMatch[1]
        };
      }
    }

    // Look for Type lines
    if (line.startsWith('**Type:**') && currentCredential) {
      const typeMatch = line.match(/\*\*Type:\*\*\s*(.+)/);
      if (typeMatch) {
        currentCredential.type = typeMatch[1].trim();
      }
    }

    // Look for Full Value lines
    if (line.startsWith('**Full Value:**') && currentCredential) {
      // Get the value which might be on the same line or next line
      const valueMatch = line.match(/\*\*Full Value:\*\*\s*`([^`]+)`/);
      if (valueMatch) {
        currentCredential.value = valueMatch[1];
        currentCredential.status = 'PRE-ROTATION';
        currentCredential.canary_marker = currentCredential.value.includes('CANARY');

        // Add to credentials array
        credentials.push(currentCredential);
        currentCredential = null;
      }
    }
  }

  return credentials;
}

