// config/secrets.js
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.lastRefresh = {};

    // Configure AWS SDK (credentials should come from environment or IAM role)
    if (process.env.AWS_REGION) {
      this.secretsManager = new AWS.SecretsManager({
        region: process.env.AWS_REGION
      });
    }
  }

  async getSecret(secretName, useCache = true, ttl = 3600000) {
    // Check cache first
    if (useCache && this.cache.has(secretName)) {
      const { value, timestamp } = this.cache.get(secretName);
      if (Date.now() - timestamp < ttl) {
        return value;
      }
    }

    // Development fallback to environment variables
    if (process.env.NODE_ENV === 'development') {
      const value = process.env[secretName];
      if (value) {
        this.cache.set(secretName, { value, timestamp: Date.now() });
        return value;
      }
    }

    // Production: fetch from AWS Secrets Manager
    if (this.secretsManager) {
      try {
        const data = await this.secretsManager
          .getSecretValue({ SecretId: secretName })
          .promise();

        let secret;
        if ('SecretString' in data) {
          secret = data.SecretString;
        } else {
          secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
        }

        this.cache.set(secretName, { 
          value: secret, 
          timestamp: Date.now() 
        });

        return secret;
      } catch (err) {
        console.error(`Error fetching secret ${secretName}:`, err.message);
        throw err;
      }
    }

    throw new Error(`Secret ${secretName} not found`);
  }

  async getJsonSecret(secretName) {
    const secret = await this.getSecret(secretName);
    return JSON.parse(secret);
  }
}

module.exports = new SecretsManager();
