// config/env-validator.js
class EnvironmentValidator {
  static validate() {
    const env = process.env.NODE_ENV || 'development';

    // Common validation rules
    const rules = {
      development: [
        { var: 'PORT', required: false, default: 3000 },
        { var: 'DATABASE_URL', required: false }
      ],
      test: [
        { var: 'TEST_DATABASE_URL', required: true },
        { var: 'NODE_ENV', required: true, value: 'test' }
      ],
      production: [
        { var: 'PORT', required: true },
        { var: 'AWS_REGION', required: true },
        { var: 'DB_SECRET_NAME', required: true },
        // Ensure no .env files are used in production
        { 
          var: 'DOTENV_CONFIG_PATH', 
          required: false,
          validator: (val) => !val,
          message: 'DOTENV_CONFIG_PATH should not be set in production'
        }
      ]
    };

    const envRules = rules[env] || [];

    for (const rule of envRules) {
      const value = process.env[rule.var];

      if (rule.required && !value) {
        throw new Error(`Required environment variable ${rule.var} is not set`);
      }

      if (rule.validator && value) {
        if (!rule.validator(value)) {
          throw new Error(rule.message || `Validation failed for ${rule.var}`);
        }
      }

      if (rule.value && value !== rule.value) {
        console.warn(`${rule.var} is set to ${value}, expected ${rule.value}`);
      }

      // Set default if not provided
      if (!value && rule.default !== undefined) {
        process.env[rule.var] = rule.default.toString();
      }
    }

    // Additional security checks
    this.checkForSensitiveDataInEnv();
  }

  static checkForSensitiveDataInEnv() {
    const sensitivePatterns = [
      /password/i,
      /secret/i,
      /key/i,
      /token/i,
      /auth/i,
      /credential/i
    ];

    const envVars = Object.keys(process.env);

    for (const envVar of envVars) {
      for (const pattern of sensitivePatterns) {
        if (pattern.test(envVar)) {
          const value = process.env[envVar];
          if (value && value.includes('CANARY')) {
            console.warn(`⚠️  WARNING: ${envVar} contains canary value. This might indicate test credentials in production!`);
          }
          if (value && value.length > 50) {
            console.warn(`⚠️  WARNING: ${envVar} value is unusually long (${value.length} chars). Verify this is not a secret in plain text.`);
          }
        }
      }
    }
  }
}

module.exports = EnvironmentValidator;
