// config.js - Secure configuration management
const fs = require('fs');
const path = require('path');

class Config {
  constructor() {
    this.secrets = {};
    this.loadSecrets();
  }

  loadSecrets() {
    // Priority 1: Environment variables (highest priority)
    this.secrets = { ...process.env };

    // Priority 2: Docker secrets (if running in container)
    if (process.env.DATABASE_PASSWORD_FILE) {
      try {
        this.secrets.DATABASE_PASSWORD = fs.readFileSync(
          process.env.DATABASE_PASSWORD_FILE, 
          'utf8'
        ).trim();
      } catch (error) {
        console.warn('Could not load Docker secret:', error.message);
      }
    }

    // Priority 3: Local .env file (development only)
    if (process.env.NODE_ENV === 'development') {
      try {
        const envPath = path.join(__dirname, '.env.local');
        if (fs.existsSync(envPath)) {
          const envContent = fs.readFileSync(envPath, 'utf8');
          envContent.split('\n').forEach(line => {
            const [key, ...value] = line.split('=');
            if (key && !this.secrets[key]) {
              this.secrets[key] = value.join('=');
            }
          });
        }
      } catch (error) {
        console.warn('Could not load .env.local:', error.message);
      }
    }

    this.validateSecrets();
  }

  validateSecrets() {
    const required = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY'
    ];

    const missing = required.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      console.error(`❌ Missing required secrets: ${missing.join(', ')}`);

      if (process.env.NODE_ENV === 'production') {
        console.error('Cannot start in production without required secrets');
        process.exit(1);
      }
    }
  }

  get(key, defaultValue = null) {
    return this.secrets[key] || defaultValue;
  }
}

module.exports = new Config();
```

