function determinePriority(varName) {
  const highPriority = ['DATABASE_URL', 'AWS_SECRET_ACCESS_KEY', 'STRIPE_SECRET_KEY'];
  const mediumPriority = ['AWS_ACCESS_KEY_ID', 'ANTHROPIC_API_KEY'];

