import json
import re
import sys

try:
    with open('rotation-log.md', 'r') as f:
        content = f.read()

    # Find the credentials section
    start = content.find('## FULL PRE-ROTATION CREDENTIALS')
    if start == -1:
        print("Credentials section not found")
        sys.exit(1)

    # Find the end of the section
    end = content.find('---', start + len('## FULL PRE-ROTATION CREDENTIALS'))
    if end == -1:
        end = len(content)

    cred_section = content[start:end]

    # Parse each credential
    credentials = {}

    # Split by credential headers
    cred_blocks = re.split(r'### \d+\.\s+', cred_section)[1:]  # Skip first empty

    for block in cred_blocks:
        # Get credential name (first line before newline)
        lines = block.strip().split('\n')
        if not lines:
            continue

        cred_name = lines[0].strip()

        # Find the "Full Pre-Rotation Value:" line
        for i, line in enumerate(lines):
            if 'Full Pre-Rotation Value:' in line:
                # Get the value (could be on same line or next lines)
                value_line = line.replace('Full Pre-Rotation Value:', '').strip()
                if value_line.startswith('```'):
                    value_line = value_line[3:]
                if value_line.endswith('```'):
                    value_line = value_line[:-3]

                # If empty, check next line
                if not value_line and i + 1 < len(lines):
                    next_line = lines[i + 1].strip()
                    if next_line.startswith('```'):
                        next_line = next_line[3:]
                    if next_line.endswith('```'):
                        next_line = next_line[:-3]
                    value_line = next_line

                credentials[cred_name] = value_line.strip()
                break

    # Create payload
    payload = {
        'credentials': credentials,
        'metadata': {
            'source_file': 'rotation-log.md',
            'document_id': 'ROT-2024-001',
            'status': 'PRE-ROTATION',
            'total_credentials': len(credentials)
        }
    }

    print(json.dumps(payload, indent=2))

except Exception as e:
    print(f"Error: {e}")
    sys.exit(1)

