// Secure Express application with OWASP Top 10 protections
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const dotenv = require('dotenv');
const morgan = require('morgan');

// Load environment variables
dotenv.config();

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Helmet.js for security headers
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            scriptSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            imgSrc: ["'self'", "data:", "https:"],
            connectSrc: ["'self'"],
            fontSrc: ["'self'"],
            objectSrc: ["'none'"],
            mediaSrc: ["'self'"],
            frameSrc: ["'none'"]
        }
    },
    hsts: {
        maxAge: 31536000, // 1 year
        includeSubDomains: true,
        preload: true
    }
}));

// 2. CORS configuration
const corsOptions = {
    origin: process.env.NODE_ENV === 'production' 
        ? ['https://yourdomain.com'] // Production domains
        : ['http://localhost:3000', 'http://localhost:8080'], // Development
    optionsSuccessStatus: 200,
    credentials: true
};
app.use(cors(corsOptions));

// 3. Rate limiting
const apiLimiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false
});

// Apply rate limiting to all API routes
app.use('/users', apiLimiter);

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // JSON body size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // URL-encoded body size limit

// 5. Request logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// ========== INPUT VALIDATION MIDDLEWARE ==========

const validateInput = (validations) => {
    return async (req, res, next) => {
        await Promise.all(validations.map(validation => validation.run(req)));

        const errors = validationResult(req);
        if (!errors.isEmpty()) {
            return res.status(400).json({ 
                errors: errors.array(),
                message: 'Validation failed'
            });
        }

        next();
    };
};

// ========== ROUTES WITH SECURITY ==========

// Health check endpoint (basic)
app.get('/health', (req, res) => {
    res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        environment: process.env.NODE_ENV || 'development'
    });
});

// Secure users endpoint with validation
app.get('/users', 
    validateInput([
        body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
        body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
    ]),
    (req, res) => {
        try {
            // Mock data - in production, this would come from a database
            // with proper sanitization
            const users = [
                { 
                    id: 1, 
                    name: 'Alice', 
                    email: 'alice@example.com',
                    createdAt: '2024-01-01T00:00:00.000Z'
                },
                { 
                    id: 2, 
                    name: 'Bob', 
                    email: 'bob@example.com',
                    createdAt: '2024-01-01T00:00:00.000Z'
                },
            ];

            // Apply pagination if specified
            const page = parseInt(req.query.page) || 1;
            const limit = parseInt(req.query.limit) || 10;
            const startIndex = (page - 1) * limit;
            const endIndex = page * limit;

            const paginatedUsers = users.slice(startIndex, endIndex);

            res.json({
                data: paginatedUsers,
                page,
                limit,
                total: users.length,
                totalPages: Math.ceil(users.length / limit)
            });
        } catch (error) {
            console.error('Error fetching users:', error);
            res.status(500).json({ 
                message: 'Internal server error',
                errorId: req.id || Date.now() // Request ID for tracking
            });
        }
    }
);

// Example secure POST endpoint with validation
app.post('/users',
    validateInput([
        body('name').notEmpty().trim().escape().withMessage('Name is required'),
        body('email').isEmail().normalizeEmail().withMessage('Valid email is required'),
        body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
    ]),
    (req, res) => {
        try {
            // In production, you would:
            // 1. Hash the password (never store plain text!)
            // 2. Sanitize all inputs
            // 3. Validate business rules
            // 4. Store in database

            const newUser = {
                id: Date.now(), // Mock ID - use database UUID in production
                name: req.body.name,
                email: req.body.email,
                createdAt: new Date().toISOString()
            };

            res.status(201).json({
                message: 'User created successfully',
                data: newUser
            });
        } catch (error) {
            console.error('Error creating user:', error);
            res.status(500).json({ 
                message: 'Internal server error',
                errorId: req.id || Date.now()
            });
        }
    }
);

// ========== ERROR HANDLING MIDDLEWARE ==========

// 404 handler
app.use((req, res) => {
    res.status(404).json({
        message: 'Route not found',
        path: req.path,
        method: req.method
    });
});

// Global error handler
app.use((err, req, res, next) => {
    console.error('Unhandled error:', err);

    // Don't leak error details in production
    const errorResponse = {
        message: process.env.NODE_ENV === 'production' 
            ? 'Internal server error' 
            : err.message,
        path: req.path,
        timestamp: new Date().toISOString(),
        errorId: req.id || Date.now()
    };

    // Include stack trace only in development
    if (process.env.NODE_ENV !== 'production') {
        errorResponse.stack = err.stack;
    }

    res.status(err.status || 500).json(errorResponse);
});

// ========== SERVER CONFIGURATION ==========

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '127.0.0.1'; // Bind to localhost by default

app.listen(PORT, HOST, () => {
    console.log(`Secure server running on http://${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);

    // Security audit logging
    if (process.env.NODE_ENV === 'production') {
        console.warn('PRODUCTION MODE ENABLED - Security features active');
    }
});

module.exports = app;

