// Secure Secrets Manager Implementation
// Replace dotenv with proper secrets management

class SecretsManager {
    constructor() {
        this.secrets = {};
        this.initialized = false;
        this.useLocalFallback = process.env.NODE_ENV === 'development';
    }

    async initialize() {
        if (this.initialized) return;

        try {
            if (this.useLocalFallback) {
                // Development: Load from .env (with warnings)
                console.warn('⚠️ Using local .env file for secrets - NOT FOR PRODUCTION');
                const dotenv = require('dotenv');
                dotenv.config();
                this.secrets = process.env;
            } else {
                // Production: Use proper secrets manager
                await this.loadFromSecretsManager();
            }

            this.validateRequiredSecrets();
            this.initialized = true;
            console.log('✅ Secrets manager initialized');

        } catch (error) {
            console.error('❌ Failed to initialize secrets manager:', error);
            throw error;
        }
    }

    async loadFromSecretsManager() {
        // Implementation for AWS Secrets Manager
        if (process.env.AWS_REGION) {
            return await this.loadFromAWSSecretsManager();
        }

        // Implementation for HashiCorp Vault
        if (process.env.VAULT_ADDR) {
            return await this.loadFromVault();
        }

        // Implementation for Google Secret Manager
        if (process.env.GOOGLE_CLOUD_PROJECT) {
            return await this.loadFromGoogleSecretManager();
        }

        throw new Error('No secrets manager configured');
    }

    async loadFromAWSSecretsManager() {
        const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

        const client = new SecretsManagerClient({
            region: process.env.AWS_REGION
        });

        const secretNames = [
            'app/database-url',
            'app/aws-credentials',
            'app/api-keys',
            'app/stripe-keys'
        ];

        for (const secretName of secretNames) {
            try {
                const command = new GetSecretValueCommand({
                    SecretId: secretName
                });

                const response = await client.send(command);
                const secretValue = JSON.parse(response.SecretString);

                // Merge secrets into this.secrets
                Object.assign(this.secrets, secretValue);

            } catch (error) {
                console.error(`Failed to load secret ${secretName}:`, error);
                // Don't throw for missing optional secrets
                if (error.name !== 'ResourceNotFoundException') {
                    throw error;
                }
            }
        }
    }

    async loadFromVault() {
        const vault = require('node-vault')({
            apiVersion: 'v1',
            endpoint: process.env.VAULT_ADDR,
            token: process.env.VAULT_TOKEN
        });

        try {
            // Read database credentials
            const dbSecret = await vault.read('secret/data/app/database');
