// Secure Configuration Loader
// Integrates with secrets manager for production, falls back to .env for development

const secretsManager = require('./secrets_manager');

class Config {
    constructor() {
        this.config = {};
        this.initialized = false;
    }

    async initialize() {
        if (this.initialized) return;

        try {
            // Initialize secrets manager first
            await secretsManager.initialize();

            // Load configuration
            this.config = {
                // Application settings
                nodeEnv: this.getEnv('NODE_ENV', 'development'),
                port: parseInt(this.getEnv('PORT', '3000')),
                host: this.getEnv('HOST', '127.0.0.1'),

                // Security settings
                sessionSecret: this.getSecret('SESSION_SECRET'),
                jwtSecret: this.getSecret('JWT_SECRET'),

                // Database configuration
                database: {
                    url: this.getSecret('DATABASE_URL'),
                    pool: {
                        min: parseInt(this.getEnv('DB_POOL_MIN', '2')),
                        max: parseInt(this.getEnv('DB_POOL_MAX', '10')),
                        idleTimeout: parseInt(this.getEnv('DB_IDLE_TIMEOUT', '30000'))
                    }
                },

                // API Keys (loaded from secrets manager)
                apiKeys: {
                    stripe: this.getSecret('STRIPE_SECRET_KEY'),
                    anthropic: this.getSecret('ANTHROPIC_API_KEY'),
                    logfire: this.getSecret('LOGFIRE_TOKEN')
                },

                // AWS Configuration
                aws: {
                    accessKeyId: this.getSecret('AWS_ACCESS_KEY_ID'),
                    secretAccessKey: this.getSecret('AWS_SECRET_ACCESS_KEY'),
                    region: this.getEnv('AWS_REGION', 'us-east-1')
                },

                // Security configuration
                security: {
                    corsOrigins: this.parseList(this.getEnv('CORS_ORIGINS', 'http://localhost:3000')),
                    rateLimitWindowMs: parseInt(this.getEnv('RATE_LIMIT_WINDOW_MS', '900000')),
                    rateLimitMaxRequests: parseInt(this.getEnv('RATE_LIMIT_MAX_REQUESTS', '100')),
                    requestSizeLimit: this.getEnv('REQUEST_SIZE_LIMIT', '10kb')
                },

                // Logging configuration
                logging: {
                    level: this.getEnv('LOG_LEVEL', 'info'),
                    format: this.getEnv('LOG_FORMAT', 'json')
                }
            };

            this.validateConfig();
            this.initialized = true;
            console.log('✅ Configuration loaded successfully');

        } catch (error) {
            console.error('❌ Failed to load configuration:', error);
            throw error;
        }
    }

    getEnv(key, defaultValue) {
        // First try environment variable
        if (process.env[key]) {
            return process.env[key];
        }

        // Then try secrets manager
        const secretValue = secretsManager.get(key);
        if (secretValue) {
            return secretValue;
        }

        // Return default if provided
        if (defaultValue !== undefined) {
            return defaultValue;
        }

        throw new Error(`Configuration key "${key}" not found and no default provided`);
    }

    getSecret(key) {
        const value = secretsManager.get(key);
        if (!value) {
            console.warn(`⚠️ Secret "${key}" not found in secrets manager`);
        }
        return value;
    }

    parseList(value) {
        if (!value) return [];
        return value.split(',').map(item => item.trim());
    }

    validateConfig() {
        const errors = [];

        // Validate required configuration
        if (!this.config.database.url) {
            errors.push('DATABASE_URL is required');
        }

        if (!this.config.sessionSecret || this.config.sessionSecret === 'change-this-to-a-very-long-random-string') {
            errors.push('SESSION_SECRET must be set to a secure random string');
        }

        if (!this.config.jwtSecret || this.config.jwtSecret === 'another-very-long-random-string') {
            errors.push('JWT_SECRET must be set to a secure random string');
        }

        // Validate security settings
        if (this.config.nodeEnv === 'production') {
            if (this.config.host === '127.0.0.1') {
                errors.push('In production, HOST should be 0.0.0.0 or specific interface');
            }

            if (this.config.sessionSecret.length < 32) {
                errors.push('SESSION_SECRET must be at least 32 characters in production');
            }
        }

        if (errors.length > 0) {
            throw new Error(`Configuration validation failed:\n${errors.join('\n')}`);
        }
    }

    get(key) {
        if (!this.initialized) {
            throw new Error('Configuration not initialized');
        }

        const keys = key.split('.');
        let value = this.config;

        for (const k of keys) {
            if (value === undefined || value === null) {
                return undefined;
            }
            value = value[k];
        }

        return value;
    }

    getAll() {
        if (!this.initialized) {
            throw new Error('Configuration not initialized');
        }

        // Return a deep copy to prevent modification
        return JSON.parse(JSON.stringify(this.config));
    }

    isProduction() {
        return this.config.nodeEnv === 'production';
    }

    isDevelopment() {
        return this.config.nodeEnv === 'development';
    }

    isTest() {
        return this.config.nodeEnv === 'test';
    }
}

