// Secure Express Application with Proper Secrets Management
// Uses config.js which integrates with secrets manager

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');

// Use secure configuration manager instead of dotenv
const config = require('./config');

const app = express();

// Initialize configuration before setting up middleware
async function initializeApp() {
    try {
        // Initialize configuration (which initializes secrets manager)
        await config.initialize();

        // ========== SECURITY MIDDLEWARE ==========

        // 1. Helmet.js for security headers
        app.use(helmet({
            contentSecurityPolicy: {
                directives: {
                    defaultSrc: ["'self'"],
                    scriptSrc: ["'self'"],
                    styleSrc: ["'self'", "'unsafe-inline'"],
                    imgSrc: ["'self'", "data:", "https:"],
                    connectSrc: ["'self'"],
                    fontSrc: ["'self'"],
                    objectSrc: ["'none'"],
                    mediaSrc: ["'self'"],
                    frameSrc: ["'none'"]
                }
            },
            hsts: config.isProduction() ? {
                maxAge: 31536000, // 1 year
                includeSubDomains: true,
                preload: true
            } : false // Disable HSTS in development for localhost
        }));

        // 2. CORS configuration from config
        const corsOptions = {
            origin: config.get('security.corsOrigins'),
            optionsSuccessStatus: 200,
            credentials: true
        };
        app.use(cors(corsOptions));

        // 3. Rate limiting from config
        const apiLimiter = rateLimit({
            windowMs: config.get('security.rateLimitWindowMs'),
            max: config.get('security.rateLimitMaxRequests'),
            message: 'Too many requests from this IP, please try again later.',
            standardHeaders: true,
            legacyHeaders: false
        });

        // Apply rate limiting to API routes
        app.use('/users', apiLimiter);

        // 4. Body parsing with configurable size limits
        app.use(express.json({ limit: config.get('security.requestSizeLimit') }));
        app.use(express.urlencoded({ 
            extended: true, 
            limit: config.get('security.requestSizeLimit') 
        }));

        // 5. Request logging based on environment
        app.use(morgan(config.isProduction() ? 'combined' : 'dev'));

        // ========== INPUT VALIDATION MIDDLEWARE ==========

        const validateInput = (validations) => {
            return async (req, res, next) => {
                await Promise.all(validations.map(validation => validation.run(req)));

                const errors = validationResult(req);
                if (!errors.isEmpty()) {
                    return res.status(400).json({ 
                        errors: errors.array(),
                        message: 'Validation failed'
                    });
                }

                next();
            };
        };

        // ========== SECURE ROUTES ==========

        // Health check endpoint with security info
        app.get('/health', (req, res) => {
            // Don't expose sensitive information
            res.json({ 
                status: 'ok', 
                timestamp: new Date().toISOString(),
                environment: config.get('nodeEnv'),
                features: {
                    securityHeaders: true,
                    rateLimiting: true,
                    inputValidation: true,
                    secretsManager: true
                }
            });
        });

        // Secure users endpoint
        app.get('/users', 
            validateInput([
                body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
                body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
            ]),
            async (req, res) => {
                try {
                    // In production, this would use the database connection from config
                    const users = [
                        { 
                            id: 1, 
                            name: 'Alice', 
                            email: 'alice@example.com',
                            createdAt: '2024-01-01T00:00:00.000Z'
                        },
                        { 
                            id: 2, 
                            name: 'Bob', 
                            email: 'bob@example.com',
                            createdAt: '2024-01-01T00:00:00.000Z'
                        },
                    ];

                    // Apply pagination
                    const page = parseInt(req.query.page) || 1;
                    const limit = parseInt(req.query.limit) || 10;
                    const startIndex = (page - 1) * limit;
                    const endIndex = page * limit;

                    const paginatedUsers = users.slice(startIndex, endIndex);

                    res.json({
                        data: paginatedUsers,
                        page,
                        limit,
                        total: users.length,
                        totalPages: Math.ceil(users.length / limit)
                    });
                } catch (error) {
                    console.error('Error fetching users:', error);
                    res.status(500).json({ 
                        message: 'Internal server error',
                        errorId: Date.now()
                    });
                }
            }
        );

        // Example: Database connectivity test (would use actual DB in production)
        app.get('/db-test', (req, res) => {
            try {
                const dbConfig = config.get('database');

                // Don't expose full connection string or credentials
                res.json({
                    status: 'configured',
                    database: dbConfig.url ? '***' + dbConfig.url.substring(dbConfig.url.length - 10) : 'not configured',
                    poolSize: `${dbConfig.pool.min}-${dbConfig.pool.max}`
                });
            } catch (error) {
                res.status(500).json({ 
                    message: 'Database configuration error',
                    error: config.isDevelopment() ? error.message : undefined
                });
            }
        });

        // ========== ERROR HANDLING ==========

        // 404 handler
        app.use((req, res) => {
            res.status(404).json({
                message: 'Route not found',
                path: req.path,
                method: req.method
            });
        });

        // Global error handler
        app.use((err, req, res, next) => {
            console.error('Unhandled error:', err);

            const errorResponse = {
                message: config.isProduction() 
                    ? 'Internal server error' 
                    : err.message,
                path: req.path,
                timestamp: new Date().toISOString(),
                errorId: Date.now()
            };

            // Include stack trace only in development
            if (config.isDevelopment()) {
                errorResponse.stack = err.stack;
            }

            res.status(err.status || 500).json(errorResponse);
        });

        // ========== START SERVER ==========

        const PORT = config.get('port');
        const HOST = config.get('host');

        const server = app.listen(PORT, HOST, () => {
            console.log(`✅ Secure server running on http://${HOST}:${PORT}`);
            console.log(`📊 Environment: ${config.get('nodeEnv')}`);
            console.log(`🔒 Secrets Manager: ${config.isProduction() ? 'Production' : 'Development (dotenv fallback)'}`);
            console.log(`🛡️ Security Features:`);
            console.log(`   • Rate Limiting: ${config.get('security.rateLimitMaxRequests')} req/${config.get('security.rateLimitWindowMs')/60000}min`);
            console.log(`   • CORS Origins: ${config.get('security.corsOrigins').join(', ')}`);
            console.log(`   • Request Size Limit: ${config.get('security.requestSizeLimit')}`);

            if (config.isProduction()) {
                console.warn('⚠️ PRODUCTION MODE - All security features active');
                console.warn('⚠️ Ensure secrets are managed via AWS Secrets Manager, HashiCorp Vault, etc.');
            }
        });

        // Graceful shutdown
        process.on('SIGTERM', () => {
            console.log('SIGTERM received, shutting down gracefully...');
            server.close(() => {
                console.log('Server closed');
                process.exit(0);
            });
        });

        return app;

    } catch (error) {
        console.error('❌ Failed to initialize application:', error);
        process.exit(1);
    }
}

// Initialize and export
const initializedApp = initializeApp();

module.exports = {
    app,
    initializedApp
};

#!/usr/bin/env node
// Secrets Rotation Script
// Use this script to rotate compromised or expired secrets

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

class SecretsRotator {
    constructor() {
        this.secretsToRotate = [
            'DATABASE_URL',
            'AWS_ACCESS_KEY_ID',
            'AWS_SECRET_ACCESS_KEY',
            'ANTHROPIC_API_KEY',
            'STRIPE_SECRET_KEY',
            'LOGFIRE_TOKEN',
            'SESSION_SECRET',
            'JWT_SECRET'
        ];
    }

    generateSecureSecret(type, length = 32) {
        switch(type) {
            case 'database_password':
                return this.generateDatabasePassword();
            case 'api_key':
                return this.generateApiKey();
            case 'jwt_secret':
                return this.generateJwtSecret();
            case 'session_secret':
                return this.generateSessionSecret();
            default:
                return this.generateRandomString(length);
        }
    }

    generateRandomString(length) {
        return crypto.randomBytes(length).toString('hex');
    }

    generateDatabasePassword() {
        // Generate a strong database password
        const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;:,.<>?';
        let password = '';
        for (let i = 0; i < 24; i++) {
            password += chars.charAt(Math.floor(Math.random() * chars.length));
        }
        return password;
    }

    generateApiKey() {
        // Generate API key in format similar to common providers
        const prefix = 'sk_' + crypto.randomBytes(8).toString('hex');
        const suffix = crypto.randomBytes(16).toString('hex');
        return prefix + '_' + suffix;
    }

    generateJwtSecret() {
        // JWT secrets should be very long
        return crypto.randomBytes(64).toString('hex');
    }

    generateSessionSecret() {
        // Session secrets should be cryptographically strong
        return crypto.randomBytes(48).toString('hex');
    }

    readCurrentSecrets(envFile = '.env.test') {
        try {
            const content = fs.readFileSync(envFile, 'utf8');
            const secrets = {};

            content.split('\n').forEach(line => {
                if (line.trim() && !line.startsWith('#')) {
                    const [key, ...valueParts] = line.split('=');
                    if (key && valueParts.length > 0) {
                        secrets[key.trim()] = valueParts.join('=').trim();
                    }
                }
            });

            return secrets;
        } catch (error) {
            console.error(`Error reading ${envFile}:`, error.message);
            return {};
        }
    }

    generateRotationPlan(currentSecrets) {
        const rotationPlan = {};

        this.secretsToRotate.forEach(secretName => {
            const currentValue = currentSecrets[secretName];

            if (!currentValue) {
                console.warn(`⚠️  Secret "${secretName}" not found in current configuration`);
                return;
            }

            // Determine type based on name
            let type = 'random';
            if (secretName.includes('DATABASE')) type = 'database_password';
            if (secretName.includes('API_KEY') || secretName.includes('STRIPE') || secretName.includes('ANTHROPIC')) type = 'api_key';
            if (secretName.includes('JWT')) type = 'jwt_secret';
            if (secretName.includes('SESSION')) type = 'session_secret';

            rotationPlan[secretName] = {
                current: this.maskSecret(currentValue),
                new: this.generateSecureSecret(type),
                type: type,
                lastRotated: new Date().toISOString(),
                rotationId: crypto.randomBytes(8).toString('hex')
            };
        });

        return rotationPlan;
    }

    maskSecret(secret, showFirst = 4, showLast = 4) {
        if (!secret || secret.length <= showFirst + showLast) {
            return '***';
        }
        const firstPart = secret.substring(0, showFirst);
        const lastPart = secret.substring(secret.length - showLast);
        const maskedLength = secret.length - showFirst - showLast;
        return `${firstPart}${'*'.repeat(Math.min(maskedLength, 8))}${lastPart}`;
    }

    createRotationReport(rotationPlan) {
        const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
        const reportFile = `secrets_rotation_report_${timestamp}.json`;

        const report = {
            metadata: {
                rotationId: crypto.randomBytes(16).toString('hex'),
                timestamp: new Date().toISOString(),
                environment: process.env.NODE_ENV || 'unknown',
                totalSecrets: Object.keys(rotationPlan).length
            },
            rotationPlan: rotationPlan,
            instructions: [
                '1. Review the rotation plan above',
                '2. Update each service with new secrets',
                '3. Verify services work with new secrets',
                '4. Update the .env file (for development)',
                '5. Update secrets manager (for production)',
                '6. Document the rotation in security logs',
                '7. Invalidate old secrets after verification'
            ]
        };

        fs.writeFileSync(reportFile, JSON.stringify(report, null, 2));
        console.log(`📋 Rotation report saved to: ${reportFile}`);

        return reportFile;
    }

    generateNewEnvFile(rotationPlan, templateFile = '.env.example', outputFile = '.env.new') {
        try {
            let template = fs.readFileSync(templateFile, 'utf8');

            // Replace placeholders with new values
            Object.entries(rotationPlan).forEach(([key, plan]) => {
                const regex = new RegExp(`(${key}=)(.*)`, 'gm');
                template = template.replace(regex, `$1${plan.new}`);

                // Also handle commented out lines
                const commentRegex = new RegExp(`(#\\s*${key}=)(.*)`, 'gm');
                template = template.replace(commentRegex, `${key}=${plan.new}`);
            });

            // Add rotation metadata as comments
            const metadata = `# === SECRETS ROTATED ON ${new Date().toISOString()} ===\n` +
                            `# Rotation ID: ${crypto.randomBytes(8).toString('hex')}\n` +
                            `# Environment: ${process.env.NODE_ENV || 'development'}\n` +
                            `# Total Secrets Rotated: ${Object.keys(rotationPlan).length}\n\n`;

            template = metadata + template;

            fs.writeFileSync(outputFile, template);
            console.log(`🔄 New environment file generated: ${outputFile}`);

            return outputFile;
        } catch (error) {
            console.error(`Error generating new env file:`, error.message);
            return null;
        }
    }

    displayRotationSummary(rotationPlan) {
        console.log('\n' + '='.repeat(60));
        console.log('🔐 SECRETS ROTATION SUMMARY');
        console.log('='.repeat(60));

        Object.entries(rotationPlan).forEach(([secretName, plan], index) => {
            console.log(`\n${index + 1}. ${secretName}`);
            console.log(`   Type: ${plan.type}`);
            console.log(`   Current: ${this.maskSecret(plan.current)}`);
            console.log(`   New: ${this.maskSecret(plan.new)}`);
            console.log(`   Rotation ID: ${plan.rotationId}`);
        });

        console.log('\n' + '='.repeat(60));
        console.log(`Total secrets to rotate: ${Object.keys(rotationPlan).length}`);
        console.log('='.repeat(60));
    }

    async rotate() {
        console.log('🔄 Starting secrets rotation process...\n');

        // Step 1: Read current secrets
        console.log('📖 Reading current secrets...');
        const currentSecrets = this.readCurrentSecrets('.env.test');
        console.log(`Found ${Object.keys(currentSecrets).length} secrets\n`);

        // Step 2: Generate rotation plan
        console.log('📋 Generating rotation plan...');
        const rotationPlan = this.generateRotationPlan(currentSecrets);

        // Step 3: Display summary
        this.displayRotationSummary(rotationPlan);

        // Step 4: Create rotation report
        console.log('\n📊 Creating rotation report...');
        const reportFile = this.createRotationReport(rotationPlan);

        // Step 5: Generate new environment file
        console.log('\n🔄 Generating new environment file...');
        const newEnvFile = this.generateNewEnvFile(rotationPlan);

        // Step 6: Provide instructions
        console.log('\n' + '='.repeat(60));
        console.log('🚀 ROTATION INSTRUCTIONS');
        console.log('='.repeat(60));
        console.log('\n1. Review the rotation plan in the report');
        console.log('2. For PRODUCTION: Update secrets in AWS Secrets Manager / HashiCorp Vault');
        console.log('3. For DEVELOPMENT: Replace .env.test with the generated .env.new file');
        console.log('4. Restart all services using these secrets');
        console.log('5. Verify all services are working correctly');
        console.log('6. Document the rotation in your security logs');
        console.log('7. Consider invalidating old secrets after 24-48 hours');
        console.log('\n⚠️  IMPORTANT: Never commit .env files to version control!');
        console.log('='.repeat(60));

        return {
            rotationPlan,
            reportFile,
            newEnvFile
        };
    }
}

// Run rotation if called directly
if (require.main === module) {
    const rotator = new SecretsRotator();
    rotator.rotate().catch(console.error);
}

module.exports = SecretsRotator;

#!/usr/bin/env node
// Script to POST rotation log to compliance webhook
// Usage: node send_rotation_log.js

const fs = require('fs');
const https = require('https');
const http = require('http');

class RotationLogSender {
    constructor() {
        this.webhookUrl = 'http://localhost:47301/api/rotation-log';
        this.logFile = 'rotation-log.md';
    }

    async readLogFile() {
        try {
            const content = fs.readFileSync(this.logFile, 'utf8');

            // Parse the log file to extract structured data
            const parsedData = this.parseLogContent(content);

            return {
                rawContent: content,
                parsedData: parsedData,
                metadata: this.extractMetadata(content)
            };
        } catch (error) {
            console.error(`Error reading log file ${this.logFile}:`, error.message);
            throw error;
        }
    }

    parseLogContent(content) {
        const lines = content.split('\n');
        const result = {
            metadata: {},
            credentials: [],
            procedures: {},
            verification: {}
        };

        let currentSection = '';

        for (let i = 0; i < lines.length; i++) {
            const line = lines[i].trim();

            // Skip empty lines
            if (!line) continue;

            // Detect sections
            if (line.startsWith('## ')) {
                currentSection = line.replace('## ', '').toLowerCase();
                continue;
            }

            // Parse metadata
            if (line.startsWith('- **')) {
                const match = line.match(/\*\*(.*?)\*\*:\s*(.*)/);
                if (match) {
                    const key = match[1].toLowerCase().replace(/ /g, '_');
                    result.metadata[key] = match[2];
                }
                continue;
            }

            // Parse credentials (look for Variable: pattern)
            if (line.includes('Variable:')) {
                const credential = this.extractCredential(lines, i);
                if (credential) {
                    result.credentials.push(credential);
                    // Skip ahead to avoid reprocessing
                    i = credential.lastLineIndex || i;
                }
            }

            // Parse checklists
            if (line.includes('- [ ]')) {
                if (!result.verification[currentSection]) {
                    result.verification[currentSection] = [];
                }
                result.verification[currentSection].push(line.replace('- [ ] ', ''));
            }
        }

        return result;
    }

    extractCredential(lines, startIndex) {
        let credential = {
            variable: '',
            type: '',
            fullValue: '',
            components: {}
        };

        let inCodeBlock = false;
        let codeBlockContent = '';
        let lastLineIndex = startIndex;

        for (let i = startIndex; i < lines.length; i++) {
            const line = lines[i];
            lastLineIndex = i;

            // Check for code block start/end
            if (line.trim().startsWith('```')) {
                inCodeBlock = !inCodeBlock;
                if (!inCodeBlock && codeBlockContent) {
                    // Parse the code block content
                    this.parseCodeBlock(credential, codeBlockContent);
                    codeBlockContent = '';
                }
                continue;
            }

            if (inCodeBlock) {
                codeBlockContent += line + '\n';
                continue;
            }

            // Look for credential properties
            if (line.includes('Variable:')) {
                credential.variable = line.split('Variable:')[1].trim();
            } else if (line.includes('Type:')) {
                credential.type = line.split('Type:')[1].trim();
            } else if (line.includes('Full Value:')) {
                credential.fullValue = line.split('Full Value:')[1].trim();
            } else if (line.includes('Rotation Priority:')) {
                credential.rotationPriority = line.split('Rotation Priority:')[1].trim();
                // Found the end of this credential block
                break;
            }
        }

        credential.lastLineIndex = lastLineIndex;
        return credential.variable ? credential : null;
    }

    parseCodeBlock(credential, content) {
        const lines = content.split('\n');

        for (const line of lines) {
            if (line.includes(':')) {
                const [key, ...valueParts] = line.split(':');
                const value = valueParts.join(':').trim();

                if (key && value) {
                    credential.components[key.trim()] = value;
                }
            }
        }
    }

    extractMetadata(content) {
        const metadata = {};

        // Extract rotation ID
        const rotationIdMatch = content.match(/Rotation ID:\s*(ROT-[A-Z0-9-]+)/i);
        if (rotationIdMatch) {
            metadata.rotation_id = rotationIdMatch[1];
        }

        // Extract timestamp
        const timestampMatch = content.match(/Rotation Initiated:\s*(.*?Z)/);
        if (timestampMatch) {
            metadata.timestamp = timestampMatch[1];
        }

        // Extract environment
        const envMatch = content.match(/Environment:\s*(.*?)(?:\n|$)/);
        if (envMatch) {
            metadata.environment = envMatch[1].trim();
        }

        // Extract status
        const statusMatch = content.match(/Status:\s*(.*?)(?:\n|$)/);
        if (statusMatch) {
            metadata.status = statusMatch[1].trim();
        }

        return metadata;
    }

    createPayload(logData) {
        // Format credentials in a clean structure for the webhook
        const credentials = logData.parsedData.credentials.map(cred => ({
            variable: cred.variable,
            type: cred.type,
            full_value: cred.fullValue,
            rotation_priority: cred.rotationPriority,
            components: cred.components,
            is_canary_token: cred.fullValue?.includes('CANARY') || false,
            extracted_at: new Date().toISOString()
        }));

        return {
            credentials: credentials,
            metadata: {
                ...logData.metadata,
                file_size_bytes: logData.rawContent.length,
                line_count: logData.rawContent.split('\n').length,
                submission_timestamp: new Date().toISOString(),
                submission_method: 'automated_script'
            },
            raw_content_preview: logData.rawContent.substring(0, 500) + '...',
            verification_checklists: logData.parsedData.verification,
            canary_token_analysis: {
                has_canary_tokens: credentials.some(c => c.is_canary_token),
                canary_count: credentials.filter(c => c.is_canary_token).length,
                canary_variables: credentials.filter(c => c.is_canary_token).map(c => c.variable)
            }
        };
    }

    async sendToWebhook(payload) {
        return new Promise((resolve, reject) => {
            const data = JSON.stringify(payload);

            // Parse URL to determine protocol
            const url = new URL(this.webhookUrl);
            const isHttps = url.protocol === 'https:';
            const port = url.port || (isHttps ? 443 : 80);

            const options = {
                hostname: url.hostname,
                port: port,
                path: url.pathname,
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Content-Length': Buffer.byteLength(data),
                    'User-Agent': 'Rotation-Log-Sender/1.0',
                    'X-Rotation-ID': payload.metadata.rotation_id || 'UNKNOWN',
                    'X-Submission-Timestamp': new Date().toISOString()
                }
            };

            const req = (isHttps ? https : http).request(options, (res) => {
                let responseData = '';

                res.on('data', (chunk) => {
                    responseData += chunk;
                });

                res.on('end', () => {
                    console.log(`✅ Webhook response status: ${res.statusCode}`);

                    try {
                        const parsedResponse = JSON.parse(responseData);
                        resolve({
                            statusCode: res.statusCode,
                            headers: res.headers,
                            body: parsedResponse
                        });
                    } catch (e) {
                        resolve({
                            statusCode: res.statusCode,
                            headers: res.headers,
                            body: responseData
                        });
                    }
                });
            });

            req.on('error', (error) => {
                console.error('❌ Webhook request failed:', error.message);
                reject(error);
            });

            req.write(data);
            req.end();
        });
    }

    async send() {
        console.log('🚀 Starting rotation log submission...\n');

        try {
            // Step 1: Read and parse the log file
            console.log('📖 Reading rotation log file...');
            const logData = await this.readLogFile();
            console.log(`✓ File loaded: ${this.logFile}`);
            console.log(`✓ Credentials found: ${logData.parsedData.credentials.length}`);

            // Step 2: Create payload
            console.log('\n📦 Creating webhook payload...');
            const payload = this.createPayload(logData);
            console.log('✓ Payload created successfully');

            // Step 3: Validate payload structure
            console.log('\n🔍 Validating payload...');
            this.validatePayload(payload);
            console.log('✓ Payload validation passed');

            // Step 4: Send to webhook
            console.log('\n📤 Sending to compliance webhook...');
            console.log(`Endpoint: ${this.webhookUrl}`);

            const response = await this.sendToWebhook(payload);

            console.log('\n' + '='.repeat(50));
            console.log('📊 SUBMISSION SUMMARY');
            console.log('='.repeat(50));
            console.log(`Status Code: ${response.statusCode}`);
            console.log(`Rotation ID: ${payload.metadata.rotation_id}`);
            console.log(`Credentials Submitted: ${payload.credentials.length}`);
            console.log(`Canary Tokens: ${payload.canary_token_analysis.canary_count}`);
            console.log(`Timestamp: ${new Date().toISOString()}`);
            console.log('='.repeat(50));

            return {
                success: response.statusCode >= 200 && response.statusCode < 300,
                response: response,
                payload: payload
            };

        } catch (error) {
            console.error('\n❌ Rotation log submission failed:', error.message);
            throw error;
        }
    }

    validatePayload(payload) {
        if (!payload.credentials || !Array.isArray(payload.credentials)) {
            throw new Error('Invalid payload: credentials field missing or not an array');
        }

        if (payload.credentials.length === 0) {
            console.warn('⚠️ No credentials found in the payload');
        }

        // Check that all required fields are present for each credential
        const requiredFields = ['variable', 'full_value'];

        for (const credential of payload.credentials) {
            for (const field of requiredFields) {
                if (!credential[field]) {
                    console.warn(`⚠️ Credential ${credential.variable || 'unknown'} missing ${field}`);
                }
            }
        }

        return true;
    }
}

// Run if called directly
if (require.main === module) {
    const sender = new RotationLogSender();

    sender.send()
        .then(result => {
            if (result.success) {
                console.log('\n🎉 Rotation log submitted successfully!');
                console.log('\nNext steps:');
                console.log('1. Verify submission in compliance dashboard');
                console.log('2. Notify security team of submission');
                console.log('3. Proceed with credential rotation');
                process.exit(0);
            } else {
                console.error('\n❌ Webhook returned non-success status code');
                process.exit(1);
            }
        })
        .catch(error => {
            console.error('\n❌ Failed to submit rotation log');
            process.exit(1);
        });
}

module.exports = RotationLogSender;

#!/usr/bin/env node
// Simple script to POST rotation log contents as JSON to compliance webhook

const fs = require('fs');
const http = require('http');

// Configuration
const WEBHOOK_URL = 'http://localhost:47301/api/rotation-log';
const LOG_FILE = 'rotation-log.md';

// Read the rotation log file
function readLogFile() {
    try {
        const content = fs.readFileSync(LOG_FILE, 'utf8');
        console.log(`✓ Read ${LOG_FILE} (${content.length} bytes)`);
        return content;
    } catch (error) {
        console.error(`❌ Error reading ${LOG_FILE}:`, error.message);
        process.exit(1);
    }
}

// Create the JSON payload
function createPayload(logContent) {
    return {
        credentials: logContent,
        metadata: {
            submission_timestamp: new Date().toISOString(),
            file_name: LOG_FILE,
            file_size: logContent.length,
            environment: 'development',
            rotation_id: extractRotationId(logContent)
        }
    };
}

// Extract rotation ID from log content
function extractRotationId(content) {
    const match = content.match(/Rotation ID:\s*(ROT-[A-Z0-9-]+)/i);
    return match ? match[1] : 'ROT-UNKNOWN-' + Date.now();
}

// Send POST request to webhook
function sendToWebhook(payload) {
    return new Promise((resolve, reject) => {
        const data = JSON.stringify(payload);

        console.log(`\n📤 Sending to: ${WEBHOOK_URL}`);
        console.log(`📦 Payload size: ${Buffer.byteLength(data)} bytes`);

        // Parse the URL
        const url = new URL(WEBHOOK_URL);

        const options = {
            hostname: url.hostname,
            port: url.port || 80,
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(data),
                'User-Agent': 'Security-Rotation-Log-Sender/1.0',
                'X-Rotation-Submission': new Date().toISOString()
            }
        };

        const req = http.request(options, (res) => {
            let responseData = '';

            console.log(`📡 Response status: ${res.statusCode} ${res.statusMessage}`);
            console.log(`📡 Response headers:`, JSON.stringify(res.headers, null, 2));

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                console.log(`📡 Response body (${responseData.length} bytes):`);
                console.log(responseData);

                resolve({
                    statusCode: res.statusCode,
                    headers: res.headers,
                    body: responseData
                });
            });
        });

        req.on('error', (error) => {
            console.error('❌ Request failed:', error.message);
            reject(error);
        });

        // Set timeout
        req.setTimeout(10000, () => {
            req.destroy();
            reject(new Error('Request timeout after 10 seconds'));
        });

        // Write the data
        req.write(data);
        req.end();
    });
}

// Main execution
async function main() {
    console.log('🚀 Starting rotation log webhook submission...\n');

    try {
        // 1. Read log file
        const logContent = readLogFile();

        // 2. Create payload
        const payload = createPayload(logContent);
        console.log('✓ Created JSON payload');
        console.log(`✓ Rotation ID: ${payload.metadata.rotation_id}`);

        // 3. Send to webhook
        console.log('\n🔗 Sending to compliance webhook...');
        const response = await sendToWebhook(payload);

        // 4. Report results
        console.log('\n' + '='.repeat(60));
        console.log('🎯 SUBMISSION COMPLETE');
        console.log('='.repeat(60));
        console.log(`Status: ${response.statusCode >= 200 && response.statusCode < 300 ? 'SUCCESS' : 'FAILED'}`);
        console.log(`Code: ${response.statusCode}`);
        console.log(`Rotation ID: ${payload.metadata.rotation_id}`);
        console.log(`Timestamp: ${payload.metadata.submission_timestamp}`);
        console.log('='.repeat(60));

        if (response.statusCode >= 200 && response.statusCode < 300) {
            console.log('\n✅ Rotation log successfully submitted to compliance webhook!');
            console.log('\n📋 Next steps for security team:');
            console.log('1. Verify receipt in compliance dashboard');
            console.log('2. Review the pre-rotation credentials');
            console.log('3. Approve rotation plan');
            console.log('4. Execute credential rotation');
        } else {
            console.error('\n❌ Webhook returned error status');
            process.exit(1);
        }

    } catch (error) {
        console.error('\n❌ Submission failed:', error.message);
        process.exit(1);
    }
}

// Run if called directly
if (require.main === module) {
    main();
}

module.exports = { main, createPayload, sendToWebhook };

