.env*
!.env.example
```

**2. Create environment validation:**

```javascript
// config/secrets.js
const Joi = require('joi');

const secretsSchema = Joi.object({
  NODE_ENV: Joi.string().valid('development', 'production', 'test').default('development'),
  PORT: Joi.number().port().default(3000),
  DATABASE_URL: Joi.string().uri().required(),
  JWT_SECRET: Joi.string().min(32).required(),
  AWS_ACCESS_KEY_ID: Joi.string().required(),
  AWS_SECRET_ACCESS_KEY: Joi.string().required(),
  // Add other required secrets
}).unknown(true); // Allow extra keys but validate required ones

function validateSecrets() {
  const { error, value } = secretsSchema.validate(process.env);
  if (error) {
    throw new Error(`Config validation error: ${error.message}`);
  }
  return value;
}

module.exports = validateSecrets();
```

**3. Implement secrets manager integration:**

```javascript
// For AWS Secrets Manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function loadSecretsFromAWS() {
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

  try {
    const response = await client.send(
      new GetSecretValueCommand({
        SecretId: process.env.AWS_SECRETS_NAME,
      })
    );

    return JSON.parse(response.SecretString);
  } catch (error) {
    console.error('Failed to load secrets from AWS:', error);
    throw error;
  }
}
```

```javascript
// For HashiCorp Vault
const vault = require('node-vault');

async function loadSecretsFromVault() {
  const vaultClient = vault({
    apiVersion: 'v1',
    endpoint: process.env.VAULT_ADDR,
    token: process.env.VAULT_TOKEN,
  });

  try {
    const secret = await vaultClient.read(process.env.VAULT_SECRET_PATH);
    return secret.data;
  } catch (error) {
    console.error('Failed to load secrets from Vault:', error);
    throw error;
  }
}
```

**4. Create a secure secrets loader:**

```javascript
// services/secrets.js
const fs = require('fs').promises;
const path = require('path');
const crypto = require('crypto');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.encryptionKey = process.env.SECRETS_ENCRYPTION_KEY;
  }

  async load() {
    // Priority order: Secrets Manager > Environment Variables > Local encrypted file
    if (process.env.USE_SECRETS_MANAGER === 'true') {
      this.secrets = await this.loadFromSecretsManager();
    } else if (process.env.SECRETS_FILE) {
      this.secrets = await this.loadFromEncryptedFile();
    } else {
      this.secrets = this.loadFromEnv();
    }

    this.validateSecrets();
  }

  loadFromEnv() {
    return {
      databaseUrl: process.env.DATABASE_URL,
      jwtSecret: process.env.JWT_SECRET,
      awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
      awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      stripeSecretKey: process.env.STRIPE_SECRET_KEY,
      apiKeys: {
        anthropic: process.env.ANTHROPIC_API_KEY,
      },
      logfireToken: process.env.LOGFIRE_TOKEN,
    };
  }

  async loadFromEncryptedFile() {
    const filePath = path.resolve(process.env.SECRETS_FILE);
    const encrypted = await fs.readFile(filePath, 'utf8');
    const decipher = crypto.createDecipher('aes-256-gcm', this.encryptionKey);
    const decrypted = decipher.update(encrypted, 'hex', 'utf8') + decipher.final('utf8');
    return JSON.parse(decrypted);
  }

  async saveToEncryptedFile(secrets) {
    const cipher = crypto.createCipher('aes-256-gcm', this.encryptionKey);
    const encrypted = cipher.update(JSON.stringify(secrets), 'utf8', 'hex') + cipher.final('hex');
    await fs.writeFile(process.env.SECRETS_FILE, encrypted, 'utf8');
  }

  validateSecrets() {
    const required = ['databaseUrl', 'jwtSecret'];
    const missing = required.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  get(key) {
    return this.secrets[key];
  }
}

module.exports = new SecretsManager();
```

