// SECURE Express.js application
// Implements OWASP Top 10 security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const cors = require('cors');
require('dotenv').config();

const app = express();

// ==================== ENVIRONMENT CONFIGURATION ====================
// Validate required environment variables
const requiredEnvVars = [
  'JWT_SECRET',
  'PORT',
  'NODE_ENV'
];

for (const envVar of requiredEnvVars) {
  if (!process.env[envVar]) {
    console.error(`❌ Missing required environment variable: ${envVar}`);
    process.exit(1);
  }
}

const port = process.env.PORT || 3000;
const nodeEnv = process.env.NODE_ENV || 'development';

// ==================== SECURITY MIDDLEWARE ====================

// 1. Security headers with Helmet.js
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  xssFilter: true,
  noSniff: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// Disable X-Powered-By header
app.disable('x-powered-by');

// 2. CORS configuration (only for development)
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS ? 
    process.env.ALLOWED_ORIGINS.split(',') : 
    (nodeEnv === 'development' ? 'http://localhost:3000' : ''),
  methods: ['GET'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  optionsSuccessStatus: 200
};

app.use(cors(corsOptions));

// 3. Rate limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: nodeEnv === 'production' ? 100 : 1000, // Different limits for dev/prod
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    error: 'Too many requests from this IP, please try again later'
  }
});

app.use(generalLimiter);

// 4. Request body parsing limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// ==================== AUTHENTICATION MIDDLEWARE ====================

// Simulated user database (in real app, use proper database)
const usersDB = {
  'admin': {
    id: 1,
    username: 'admin',
    passwordHash: '$2b$10$fakehashfordemo', // bcrypt hash
    role: 'admin'
  }
};

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ 
      error: 'Access token required',
      code: 'AUTH_TOKEN_MISSING'
    });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ 
        error: 'Invalid or expired token',
        code: 'AUTH_TOKEN_INVALID'
      });
    }
    req.user = user;
    next();
  });
};

// Role-based authorization middleware
const authorizeRole = (...roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      return res.status(403).json({
        error: 'Insufficient permissions',
        code: 'AUTH_INSUFFICIENT_PERMISSIONS'
      });
    }
    next();
  };
};

// ==================== ROUTES WITH INPUT VALIDATION ====================

// Public health endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: nodeEnv,
    version: '1.0.0'
  });
});

// Protected user endpoints
app.get('/users', 
  authenticateToken,
  authorizeRole('admin', 'user'),
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer'),
    query('search')
      .optional()
      .trim()
      .isLength({ min: 1, max: 50 })
      .withMessage('Search term must be between 1 and 50 characters')
      .escape() // Sanitize input
  ],
  (req, res) => {
    // Validate input before processing
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array(),
        code: 'VALIDATION_ERROR'
      });
    }

    // Safe default values for pagination
    const limit = parseInt(req.query.limit) || 10;
    const page = parseInt(req.query.page) || 1;
    const search = req.query.search || '';

    // Log the request (sanitized)
    console.log(`[${new Date().toISOString()}] User ${req.user.id} accessed /users with search: "${search}"`);

    // Return mock user data (in production, fetch from database with proper sanitization)
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        createdAt: '2024-01-01T00:00:00Z'
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        createdAt: '2024-01-02T00:00:00Z'
      },
    ];

    // Filter by search if provided (safe due to validation and escape())
    const filteredUsers = search ? 
      users.filter(user => 
        user.name.toLowerCase().includes(search.toLowerCase()) ||
        user.email.toLowerCase().includes(search.toLowerCase())
      ) : users;

    res.json({
      data: filteredUsers,
      pagination: {
        page,
        limit,
        total: filteredUsers.length,
        totalPages: Math.ceil(filteredUsers.length / limit)
      },
      meta: {
        timestamp: new Date().toISOString(),
        requestId: Math.random().toString(36).substring(7)
      }
    });
  }
);

// Login endpoint (simplified example)
