// Advanced secrets management system
// Supports multiple secret sources with fallback strategy

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

class SecretsManager {
  constructor(options = {}) {
    this.env = process.env.NODE_ENV || 'development';
    this.secretSources = options.sources || ['env', 'file'];
    this.encryptionKey = options.encryptionKey || null;
    this.cache = new Map();
  }

  // Load secrets from appropriate source based on environment
  async loadSecrets() {
    const secrets = {};

    // Priority: 1. Environment-specific files
    if (this.secretSources.includes('file')) {
      const fileSecrets = await this.loadFromEnvFile();
      Object.assign(secrets, fileSecrets);
    }

    // Priority: 2. Process environment variables (overrides files)
    if (this.secretSources.includes('env')) {
      Object.assign(secrets, this.loadFromProcessEnv());
    }

    // Priority: 3. External secrets manager (AWS, Azure, etc.)
    if (this.secretSources.includes('external')) {
      const externalSecrets = await this.loadFromExternalManager();
      Object.assign(secrets, externalSecrets);
    }

    // Priority: 4. In-memory encrypted cache (for production)
    if (this.encryptionKey && this.secretSources.includes('cache')) {
      const cachedSecrets = await this.loadFromEncryptedCache();
      Object.assign(secrets, cachedSecrets);
    }

    this.cache = new Map(Object.entries(secrets));
    return secrets;
  }

  // Load from .env files with improved security
  async loadFromEnvFile() {
    const envFiles = [];

    // Only load specific, secure .env files
    switch (this.env) {
      case 'production':
        envFiles.push('.env.production');
        break;
      case 'staging':
        envFiles.push('.env.staging');
        break;
      case 'test':
        envFiles.push('.env.test');
        break;
      default:
        envFiles.push('.env.development', '.env.local');
    }

    const secrets = {};

    for (const file of envFiles) {
      try {
        const filePath = path.resolve(process.cwd(), file);

        // Security: Check file permissions
        const stats = fs.statSync(filePath);
        if (stats.mode & 0o007) {
          console.warn(`⚠️  Security warning: ${file} has world-readable permissions`);
        }

        // Parse .env file safely
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split('\n');

        for (const line of lines) {
          if (line.trim() && !line.startsWith('#')) {
            const [key, ...valueParts] = line.split('=');
            if (key && valueParts.length > 0) {
              const value = valueParts.join('=').trim();

              // Security: Validate and sanitize values
              if (this.validateSecret(key, value)) {
                secrets[key] = this.decryptIfNeeded(value);
              } else {
                console.warn(`⚠️  Invalid secret format for key: ${key}`);
              }
            }
          }
        }

        console.log(`✅ Loaded secrets from ${file}`);
      } catch (error) {
        if (error.code !== 'ENOENT') {
          console.warn(`⚠️  Could not load ${file}:`, error.message);
        }
      }
    }

    return secrets;
  }

  // Load from process environment with validation
  loadFromProcessEnv() {
    const secrets = {};
    const secretPattern = /(SECRET|KEY|TOKEN|PASSWORD|AUTH)/i;

    for (const [key, value] of Object.entries(process.env)) {
      if (secretPattern.test(key) && value) {
        secrets[key] = value;
      }
    }

    return secrets;
  }

  // Load from external secrets manager (AWS Secrets Manager example)
