const fs = require('fs');

function redactSecret(secret) {
  if (!secret || secret.length <= 8) {
    return '[value too short to redact]';
  }
  const firstFour = secret.substring(0, 4);
  const lastFour = secret.substring(secret.length - 4);
  return `${firstFour}...${lastFour}`;
}

function analyzeSecrets(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    const secrets = [];

    lines.forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const eqIndex = line.indexOf('=');
        if (eqIndex > 0) {
          const varName = line.substring(0, eqIndex).trim();
          const value = line.substring(eqIndex + 1).trim();

          secrets.push({
            variable: varName,
            value: value,
            redacted: redactSecret(value),
            length: value.length,
            type: determineSecretType(varName, value)
          });
        }
      }
    });

    return secrets;
  } catch (error) {
    console.error('Error reading secrets file:', error.message);
    return [];
  }
}

function determineSecretType(varName, value) {
  const varLower = varName.toLowerCase();

  if (varLower.includes('url')) return 'Connection URL';
  if (varLower.includes('aws') && varLower.includes('key')) {
    if (varLower.includes('access')) return 'AWS Access Key';
    if (varLower.includes('secret')) return 'AWS Secret Key';
