/**
 * Secure Express.js application configuration
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();

// Security Middleware Configuration
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true
}));

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : [],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Body parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array(),
      message: 'Validation failed'
    });
  }
  next();
};

// Health check endpoint (no sensitive data)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.APP_VERSION || '1.0.0'
  });
});

// Secure users endpoint with input validation
app.get('/users',
  [
    // Validate query parameters
    body('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    body('page').optional().isInt({ min: 1 }).toInt(),
  ],
  validateRequest,
  async (req, res) => {
    try {
      // Sanitize input
      const limit = req.query.limit ? parseInt(req.query.limit) : 10;
      const page = req.query.page ? parseInt(req.query.page) : 1;

      // In a real app, this would come from a database with proper access controls
      const users = [
        { 
          id: 1, 
          name: 'Alice', 
          email: 'alice@example.com',
          // Don't expose sensitive information
          role: 'user'
        },
        { 
          id: 2, 
          name: 'Bob', 
          email: 'bob@example.com',
          role: 'user'
        },
      ];

      // Apply pagination (simplified)
      const startIndex = (page - 1) * limit;
      const endIndex = page * limit;
      const paginatedUsers = users.slice(startIndex, endIndex);

      res.json({
        data: paginatedUsers.map(user => ({
          id: user.id,
          name: user.name,
          // Don't expose email publicly in production without authentication
          // email: user.email // Only include for authenticated requests
        })),
        pagination: {
          page,
          limit,
          total: users.length,
          totalPages: Math.ceil(users.length / limit)
        }
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({ 
        message: 'Internal server error',
        errorId: Date.now() // Log correlation ID, not sensitive details
      });
    }
  }
);

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose stack traces in production
  const errorResponse = {
    message: 'An unexpected error occurred'
  };

  if (process.env.NODE_ENV === 'development') {
    errorResponse.error = err.message;
    errorResponse.stack = err.stack;
  }

  res.status(500).json(errorResponse);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ message: 'Resource not found' });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Server configuration
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');

/**
 * Authentication middleware
 */

// Mock user database (in production, use a real database)
const users = [
  {
    id: 1,
    username: 'admin',
    // In production, store hashed passwords
    passwordHash: '$2b$12$LQ...', // bcrypt hash of 'password123'
    role: 'admin'
  }
];

/**
 * Authenticate user with username and password
 * @param {string} username 
 * @param {string} password 
 * @returns {Promise<Object|null>} User object or null
 */
async function authenticateUser(username, password) {
  const user = users.find(u => u.username === username);
  if (!user) {
    return null;
  }

  // In production, compare with bcrypt
  // const isValid = await bcrypt.compare(password, user.passwordHash);
  // For demo purposes
  const isValid = password === 'password123';

  return isValid ? user : null;
}

/**
 * Generate JWT token
 * @param {Object} user 
 * @returns {string} JWT token
 */
function generateToken(user) {
  const payload = {
    userId: user.id,
    username: user.username,
    role: user.role,
    issuedAt: Date.now()
  };

  return jwt.sign(payload, process.env.JWT_SECRET || 'fallback-secret-change-me', {
    expiresIn: process.env.TOKEN_EXPIRY || '24h',
    issuer: 'secure-app'
  });
}

/**
 * Verify JWT token middleware
 */
function verifyToken(req, res, next) {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ 
      message: 'Authentication required' 
    });
  }

  const token = authHeader.split(' ')[1];

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET || 'fallback-secret-change-me');
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(403).json({ 
      message: 'Invalid or expired token' 
    });
  }
}

/**
 * Role-based authorization middleware
 * @param {string[]} allowedRoles 
 */
function authorize(allowedRoles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ message: 'Authentication required' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ 
        message: 'Insufficient permissions' 
      });
    }

    next();
  };
}

/**
 * Rate limiting middleware (enhanced)
 */
function createRateLimiter(maxRequests, windowMs) {
  const requests = new Map();

  return (req, res, next) => {
    const ip = req.ip || req.connection.remoteAddress;
    const now = Date.now();

    if (!requests.has(ip)) {
      requests.set(ip, []);
    }

    const userRequests = requests.get(ip);
    const windowStart = now - windowMs;

    // Clean old requests
    while (userRequests.length > 0 && userRequests[0] < windowStart) {
      userRequests.shift();
    }

    if (userRequests.length >= maxRequests) {
      return res.status(429).json({ 
        message: 'Too many requests',
        retryAfter: Math.ceil((userRequests[0] + windowMs - now) / 1000)
      });
    }

    userRequests.push(now);
    next();
  };
}

module.exports = {
  authenticateUser,
  generateToken,
  verifyToken,
  authorize,
  createRateLimiter
};

const validator = require('validator');
const { body, param } = require('express-validator');

/**
 * Input validation middleware and utilities
 */

// Common validation chains
const userValidation = [
  body('username')
    .trim()
    .isLength({ min: 3, max: 30 })
    .withMessage('Username must be between 3 and 30 characters')
    .matches(/^[a-zA-Z0-9_]+$/)
    .withMessage('Username can only contain letters, numbers, and underscores'),

  body('email')
    .trim()
    .isEmail()
    .normalizeEmail()
    .withMessage('Valid email is required'),

  body('password')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters')
    .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
    .withMessage('Password must contain uppercase, lowercase, and numbers'),
];

const queryValidation = [
  body('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be between 1 and 100'),

  body('page')
    .optional()
    .isInt({ min: 1 })
    .toInt()
    .withMessage('Page must be at least 1'),

  body('sort')
    .optional()
    .isIn(['asc', 'desc', 'name', 'date'])
    .withMessage('Invalid sort parameter'),
];

// ID parameter validation
const idValidation = [
  param('id')
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer')
    .toInt(),
];

// Sanitization functions
function sanitizeInput(input) {
  if (typeof input === 'string') {
    // Remove potentially dangerous characters
    return input
      .replace(/<[^>]*>?/gm, '') // Remove HTML tags
      .replace(/[^\w\s\-@\.]/gi, '') // Remove special characters except basic ones
      .trim();
  }
  return input;
}

function sanitizeObject(obj) {
  const sanitized = {};
  for (const [key, value] of Object.entries(obj)) {
    if (typeof value === 'string') {
      sanitized[key] = sanitizeInput(value);
    } else if (Array.isArray(value)) {
      sanitized[key] = value.map(item => 
        typeof item === 'string' ? sanitizeInput(item) : item
      );
    } else if (typeof value === 'object' && value !== null) {
      sanitized[key] = sanitizeObject(value);
    } else {
      sanitized[key] = value;
    }
  }
  return sanitized;
}

// SQL injection prevention
function sanitizeSql(input) {
  if (typeof input === 'string') {
    return input
      .replace(/['"\\\/;]/g, '') // Remove SQL special characters
      .trim();
  }
  return input;
}

// XSS prevention
function escapeHtml(text) {
  const map = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#039;'
  };
  return text.replace(/[&<>"']/g, function(m) { return map[m]; });
}

// Validate and sanitize middleware
function validateAndSanitize(validationRules) {
  return [
    ...validationRules,
    (req, res, next) => {
      // Sanitize body
      if (req.body && typeof req.body === 'object') {
        req.body = sanitizeObject(req.body);
      }

      // Sanitize query
      if (req.query && typeof req.query === 'object') {
        req.query = sanitizeObject(req.query);
      }

      // Sanitize params
      if (req.params && typeof req.params === 'object') {
        req.params = sanitizeObject(req.params);
      }

      next();
    }
  ];
}

module.exports = {
  userValidation,
  queryValidation,
  idValidation,
  sanitizeInput,
  sanitizeObject,
  sanitizeSql,
  escapeHtml,
  validateAndSanitize
};

#!/usr/bin/env node

/**
 * Security audit script for the application
 * Run with: node scripts/security-audit.js
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

console.log('🔍 Starting Security Audit\n');

const auditResults = {
  critical: [],
  high: [],
  medium: [],
  low: [],
  info: []
};

// Check 1: Package.json security dependencies
console.log('1. Checking dependencies...');
try {
  const packageJson = JSON.parse(fs.readFileSync('package.json', 'utf8'));

  // Security packages check
  const securityPackages = ['helmet', 'express-rate-limit', 'express-validator', 'bcrypt', 'jsonwebtoken'];
  const missingPackages = securityPackages.filter(pkg => !packageJson.dependencies[pkg]);

  if (missingPackages.length > 0) {
    auditResults.high.push(`Missing security packages: ${missingPackages.join(', ')}`);
  } else {
    auditResults.info.push('✓ Security dependencies installed');
  }

  // Check for known vulnerable packages
  console.log('   Running npm audit...');
  try {
    execSync('npm audit --audit-level=high', { stdio: 'pipe' });
    auditResults.info.push('✓ No high/critical vulnerabilities found in dependencies');
  } catch (error) {
    auditResults.high.push('✗ Found vulnerabilities in dependencies (run npm audit for details)');
  }
} catch (error) {
  auditResults.critical.push('✗ Cannot read package.json');
}

// Check 2: Environment file security
console.log('\n2. Checking environment configuration...');
if (fs.existsSync('.env.test')) {
  const envContent = fs.readFileSync('.env.test', 'utf8');
  const sensitivePatterns = [
    /AWS_ACCESS_KEY_ID=/,
    /AWS_SECRET_ACCESS_KEY=/,
    /DATABASE_URL=.*password/,
    /API_KEY=/,
    /SECRET=/,
    /PASSWORD=/,
    /TOKEN=/
  ];

  const foundSensitive = sensitivePatterns.filter(pattern => pattern.test(envContent));
  if (foundSensitive.length > 0) {
    auditResults.critical.push('✗ .env.test file contains sensitive credentials');
    auditResults.critical.push('   Remove this file or move credentials to secure storage');
  }
}

if (fs.existsSync('.gitignore')) {
  const gitignore = fs.readFileSync('.gitignore', 'utf8');
  if (!gitignore.includes('.env') || !gitignore.includes('node_modules')) {
    auditResults.high.push('✗ .gitignore missing critical entries');
  } else {
    auditResults.info.push('✓ .gitignore properly configured');
  }
}

// Check 3: Application code security
console.log('\n3. Analyzing application code...');
const appFiles = ['app.js', 'app-secure.js'].filter(file => fs.existsSync(file));

appFiles.forEach(file => {
  console.log(`   Checking ${file}...`);
  const content = fs.readFileSync(file, 'utf8');

  // Check for eval() usage
  if (content.includes('eval(')) {
    auditResults.critical.push(`✗ ${file} contains eval() - critical security risk`);
  }

  // Check for console.log in production code
  if (file === 'app.js' && content.includes('console.log(')) {
    auditResults.medium.push(`⚠ ${file} contains console.log() calls - potential info leak`);
  }

  // Check for basic security middleware
  if (file === 'app.js') {
    const securityChecks = [
      { pattern: 'helmet', name: 'Helmet security headers' },
      { pattern: 'rateLimit', name: 'Rate limiting' },
      { pattern: 'express-validator', name: 'Input validation' },
      { pattern: 'cors', name: 'CORS configuration' }
    ];

    securityChecks.forEach(check => {
      if (!content.includes(check.pattern)) {
        auditResults.high.push(`✗ ${file} missing ${check.name}`);
      }
    });
  }
});

// Check 4: File permissions
console.log('\n4. Checking file permissions...');
const criticalFiles = ['package.json', 'app.js', '.env.example'];
criticalFiles.forEach(file => {
  if (fs.existsSync(file)) {
    try {
      const stats = fs.statSync(file);
      const mode = stats.mode.toString(8);
      if (mode.slice(-3) !== '644' && mode.slice(-3) !== '600') {
        auditResults.medium.push(`⚠ ${file} has permissions ${mode.slice(-3)} - recommended 644`);
      }
    } catch (error) {
      auditResults.info.push(`   Could not check permissions for ${file}`);
    }
  }
});

// Check 5: HTTPS configuration
console.log('\n5. Checking HTTPS configuration...');
if (fs.existsSync('app-secure.js')) {
  const secureContent = fs.readFileSync('app-secure.js', 'utf8');
  if (!secureContent.includes('helmet.hsts')) {
    auditResults.high.push('✗ Missing HSTS configuration');
  }
  if (!secureContent.includes('ENABLE_HTTPS_REDIRECT')) {
    auditResults.medium.push('⚠ No HTTPS redirect configuration found');
  }
}

// Display results
console.log('\n' + '='.repeat(50));
console.log('SECURITY AUDIT RESULTS');
console.log('='.repeat(50));

function displayResults(level, colorCode) {
  if (auditResults[level].length > 0) {
    console.log(`\n${colorCode}${level.toUpperCase()} PRIORITY ISSUES (${auditResults[level].length}):\x1b[0m`);
    auditResults[level].forEach(issue => console.log(`  • ${issue}`));
  }
}

displayResults('critical', '\x1b[31m'); // Red
displayResults('high', '\x1b[33m');     // Yellow
displayResults('medium', '\x1b[36m');   // Cyan
displayResults('low', '\x1b[34m');      // Blue
displayResults('info', '\x1b[32m');     // Green

console.log('\n' + '='.repeat(50));

// Summary
const totalIssues = auditResults.critical.length + auditResults.high.length + 
                   auditResults.medium.length + auditResults.low.length;

if (totalIssues === 0) {
  console.log('\n✅ Excellent! No security issues found.');
} else {
  console.log(`\n📊 Summary: Found ${totalIssues} security issues`);
  console.log(`   Critical: ${auditResults.critical.length}`);
  console.log(`   High: ${auditResults.high.length}`);
  console.log(`   Medium: ${auditResults.medium.length}`);
  console.log(`   Low: ${auditResults.low.length}`);

  console.log('\n🔧 Recommended next steps:');
  if (auditResults.critical.length > 0) {
    console.log('   1. Fix CRITICAL issues immediately');
  }
  if (auditResults.high.length > 0) {
    console.log('   2. Address HIGH priority issues');
  }
  console.log('   3. Run: npm run security-audit (regularly)');
  console.log('   4. Keep dependencies updated');
}

console.log('\n📋 Generated files for security improvement:');
console.log('   • app-secure.js - Secure application template');
console.log('   • middleware/auth.js - Authentication middleware');
console.log('   • middleware/validation.js - Input validation');
console.log('   • package.json - Updated dependencies');
console.log('   • .eslintrc.json - Security-focused linting');
console.log('   • .env.example - Environment template');
console.log('   • .gitignore - Proper file exclusion');

console.log('\n🚀 To secure your application:');
console.log('   1. npm install');
console.log('   2. Copy .env.example to .env and configure');
console.log('   3. Replace app.js with app-secure.js');
console.log('   4. Run: node scripts/security-audit.js');

