/**
 * Secure Secrets Management System
 * 
 * Provides safe access to secrets with validation, encryption, and rotation support.
 * Integrates with cloud secrets managers (AWS Secrets Manager, Azure Key Vault, etc.)
 */

const crypto = require('crypto');
const { createHmac } = require('crypto');

// Mock secrets manager clients (in production, use actual SDKs)
// const AWS = require('aws-sdk');
// const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
// const { DefaultAzureCredential } = require('@azure/identity');
// const { SecretClient } = require('@azure/keyvault-secrets');

class SecretsManager {
  constructor(options = {}) {
    this.secrets = {};
    this.missingSecrets = [];
    this.secretVersions = new Map();
    this.options = {
      validateOnLoad: true,
      requireAllSecrets: true,
      enableRotation: false,
      rotationInterval: 24 * 60 * 60 * 1000, // 24 hours
      ...options
    };

    // Encryption key for local secret encryption (optional)
    this.encryptionKey = process.env.SECRET_ENCRYPTION_KEY;
  }

  /**
   * Initialize secrets from environment or external source
   */
  async initialize() {
    console.log('🔐 Initializing secrets manager...');

    try {
      // First try to load from external secrets manager
      await this.loadFromExternalManager();

      // Fallback to environment variables with validation
      if (Object.keys(this.secrets).length === 0) {
        await this.loadFromEnvironment();
      }

      // Validate required secrets
      if (this.options.validateOnLoad) {
        await this.validateSecrets();
      }

      console.log(`✅ Secrets initialized (${Object.keys(this.secrets).length} secrets loaded)`);
    } catch (error) {
      console.error('❌ Failed to initialize secrets:', error.message);
      throw error;
    }
  }

  /**
   * Load secrets from cloud secrets manager (AWS Secrets Manager example)
   */
  async loadFromExternalManager() {
    const provider = process.env.SECRETS_PROVIDER || 'env';

    switch (provider.toLowerCase()) {
      case 'aws':
        return await this.loadFromAWSSecretsManager();
      case 'azure':
        return await this.loadFromAzureKeyVault();
      case 'gcp':
        return await this.loadFromGCPSecretManager();
      case 'hashicorp':
        return await this.loadFromHashicorpVault();
      default:
        console.log('ℹ️ Using environment variables for secrets');
        return false;
    }
  }

  /**
   * Mock AWS Secrets Manager integration
   */
  async loadFromAWSSecretsManager() {
    console.log('🔐 Loading secrets from AWS Secrets Manager...');

    // In production:
    // const client = new AWS.SecretsManager({
    //   region: process.env.AWS_REGION
    // });

    // Example secrets structure
    const mockSecrets = {
      'database/credentials': JSON.stringify({
        host: process.env.DB_HOST || 'localhost',
        username: process.env.DB_USER || 'app_user',
        password: process.env.DB_PASSWORD || 'password123',
        database: process.env.DB_NAME || 'app_db'
      }),
      'api-keys': JSON.stringify({
        stripe: process.env.STRIPE_SECRET_KEY,
        anthropic: process.env.ANTHROPIC_API_KEY,
        logfire: process.env.LOGFIRE_TOKEN
      }),
      'jwt-keys': JSON.stringify({
        secret: process.env.JWT_SECRET,
        publicKey: process.env.JWT_PUBLIC_KEY,
        privateKey: process.env.JWT_PRIVATE_KEY
      })
    };

    // Process mock secrets
    for (const [secretName, secretValue] of Object.entries(mockSecrets)) {
      try {
        const parsed = JSON.parse(secretValue);
        Object.assign(this.secrets, parsed);
        this.secretVersions.set(secretName, 'v1');
      } catch (error) {
        console.warn(`⚠️ Failed to parse secret ${secretName}:`, error.message);
      }
    }

    return true;
  }

  /**
   * Load secrets from environment variables with validation
   */
  async loadFromEnvironment() {
    console.log('🔐 Loading secrets from environment variables...');

    // Required secrets (will throw if missing)
    const requiredSecrets = [
      'JWT_SECRET',
      'DATABASE_URL',
    ];

    // Optional secrets
    const optionalSecrets = [
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN',
      'SESSION_SECRET',
      'BCRYPT_SALT_ROUNDS',
      'ALLOWED_ORIGINS'
    ];

    // Load all secrets from process.env
    const allSecrets = [...requiredSecrets, ...optionalSecrets];

    for (const secretName of allSecrets) {
      const value = process.env[secretName];

      if (value) {
        // Store the secret
        this.secrets[secretName] = value;

        // Apply transformations if needed
        if (secretName === 'BCRYPT_SALT_ROUNDS') {
          this.secrets[secretName] = parseInt(value, 10);
        }

        // Log that secret was loaded (but not the value)
        console.log(`   ✓ ${secretName} loaded`);
      } else if (requiredSecrets.includes(secretName)) {
        this.missingSecrets.push(secretName);
        console.log(`   ✗ ${secretName} MISSING`);
      }
    }
  }

  /**
   * Validate that all required secrets are present
   */
  async validateSecrets() {
    if (this.missingSecrets.length > 0) {
      const errorMsg = `Missing required secrets: ${this.missingSecrets.join(', ')}`;

      if (this.options.requireAllSecrets) {
        throw new Error(errorMsg);
      } else {
        console.warn(`⚠️ ${errorMsg}`);
      }
    }

    // Validate secret formats
    await this.validateSecretFormats();

    // Rotate secrets if enabled
    if (this.options.enableRotation) {
      await this.rotateSecretsIfNeeded();
    }
  }

  /**
   * Validate secret formats
   */
  async validateSecretFormats() {
    const validations = {
      JWT_SECRET: (value) => value.length >= 32,
      DATABASE_URL: (value) => value.startsWith('postgres://') || value.startsWith('mysql://'),
      AWS_ACCESS_KEY_ID: (value) => value.startsWith('AKIA'),
      AWS_SECRET_ACCESS_KEY: (value) => value.length >= 40,
    };

    for (const [secretName, validator] of Object.entries(validations)) {
      if (this.secrets[secretName] && !validator(this.secrets[secretName])) {
        console.warn(`⚠️ ${secretName} has invalid format`);
      }
    }
  }

  /**
   * Get a secret value
   */
  get(secretName, defaultValue = null) {
    const value = this.secrets[secretName];

    if (!value && defaultValue === null && this.options.requireAllSecrets) {
      throw new Error(`Secret "${secretName}" not found and no default provided`);
    }

    return value || defaultValue;
  }

  /**
   * Get a secret with audit logging
   */
  getWithAudit(secretName, requester = 'unknown') {
    const value = this.get(secretName);

    // Log secret access (without the value)
    console.log(`🔐 Secret accessed: ${secretName} by ${requester} at ${new Date().toISOString()}`);

    // In production, send to audit log service
    // auditLogService.log({
    //   action: 'SECRET_ACCESS',
    //   secretName,
    //   requester,
    //   timestamp: new Date()
    // });

    return value;
  }

  /**
   * Get a database connection string with parsed components
   */
  getDatabaseConfig() {
    const dbUrl = this.get('DATABASE_URL');
    if (!dbUrl) return null;

    try {
      const url = new URL(dbUrl);
      return {
        host: url.hostname,
        port: url.port || 5432,
        username: url.username,
        password: url.password,
        database: url.pathname.slice(1),
        ssl: process.env.NODE_ENV === 'production'
      };
    } catch (error) {
      console.error('Failed to parse DATABASE_URL:', error.message);
      return null;
    }
  }

  /**
   * Rotate secrets if needed
   */
  async rotateSecretsIfNeeded() {
    const now = Date.now();
    const rotationInterval = this.options.rotationInterval;

    for (const [secretName, version] of this.secretVersions) {
      const lastRotation = this.secretRotationTimes.get(secretName) || 0;

      if (now - lastRotation > rotationInterval) {
        console.log(`🔄 Rotating secret: ${secretName}`);
        await this.rotateSecret(secretName);
        this.secretRotationTimes.set(secretName, now);
      }
    }
  }

  /**
   * Rotate a specific secret
   */
  async rotateSecret(secretName) {
    // In production, this would call the secrets manager API
    // to rotate the secret and update the local cache

    console.log(`🔄 Secret rotation not implemented for ${secretName}`);
    // Example: await secretsManagerClient.rotateSecret({ SecretId: secretName });
  }

  /**
   * Encrypt a secret value
   */
  encryptSecret(value, secretName) {
    if (!this.encryptionKey) return value;

    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-gcm', Buffer.from(this.encryptionKey, 'hex'), iv);

    let encrypted = cipher.update(value, 'utf8', 'hex');
    encrypted += cipher.final('hex');

    const authTag = cipher.getAuthTag();

    return {
      iv: iv.toString('hex'),
      encrypted,
      authTag: authTag.toString('hex'),
      meta: { secretName, encryptedAt: new Date().toISOString() }
    };
  }

  /**
   * Decrypt a secret value
   */
  decryptSecret(encryptedData) {
    if (!this.encryptionKey) return encryptedData;

    const iv = Buffer.from(encryptedData.iv, 'hex');
    const authTag = Buffer.from(encryptedData.authTag, 'hex');
    const decipher = crypto.createDecipheriv('aes-256-gcm', Buffer.from(this.encryptionKey, 'hex'), iv);

    decipher.setAuthTag(authTag);

    let decrypted = decipher.update(encryptedData.encrypted, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return decrypted;
  }

  /**
   * Get all loaded secret names (for auditing)
   */
  getLoadedSecrets() {
    return Object.keys(this.secrets);
  }

  /**
   * Check if a secret exists
   */
  has(secretName) {
    return secretName in this.secrets;
  }

  /**
   * Clear all secrets from memory
   */
  clear() {
    this.secrets = {};
    this.secretVersions.clear();
    console.log('🔐 All secrets cleared from memory');
  }
}

