module.exports = secretsManager;

#!/usr/bin/env node

/**
 * Secure application entry point with proper secrets management
 */

'use strict';

// Load environment variables first (but don't expose them directly)
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config({ path: '.env.local' });
}

const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

// Initialize secrets manager
const secretsManager = require('./config/secrets');

// Application configuration
const config = {
  port: parseInt(process.env.PORT || '3000', 10),
  environment: process.env.NODE_ENV || 'development',
  isProduction: process.env.NODE_ENV === 'production',
  isDevelopment: process.env.NODE_ENV === 'development',
  isTest: process.env.NODE_ENV === 'test',

  // Security flags
  enableHttps: process.env.ENABLE_HTTPS === 'true',
  enableSecurityHeaders: process.env.ENABLE_SECURITY_HEADERS !== 'false',
  enableRateLimiting: process.env.ENABLE_RATE_LIMITING !== 'false',
  enableCors: process.env.ENABLE_CORS === 'true',

  // SSL/TLS configuration (if using HTTPS)
  ssl: {
    certPath: process.env.SSL_CERT_PATH,
    keyPath: process.env.SSL_KEY_PATH,
    caPath: process.env.SSL_CA_PATH
  }
};

/**
 * Validate configuration
 */
function validateConfig() {
  console.log('🔧 Validating configuration...');

  const errors = [];

  // Port validation
  if (config.port < 1 || config.port > 65535) {
    errors.push(`Invalid port: ${config.port}`);
  }

  // HTTPS validation
  if (config.enableHttps) {
    if (!config.ssl.certPath || !config.ssl.keyPath) {
      errors.push('HTTPS enabled but SSL certificate or key path not provided');
    } else if (!fs.existsSync(config.ssl.certPath)) {
      errors.push(`SSL certificate not found: ${config.ssl.certPath}`);
    } else if (!fs.existsSync(config.ssl.keyPath)) {
      errors.push(`SSL key not found: ${config.ssl.keyPath}`);
    }
  }

  if (errors.length > 0) {
    console.error('❌ Configuration errors:');
    errors.forEach(error => console.error(`  - ${error}`));
    throw new Error('Invalid configuration');
  }

  console.log('✅ Configuration validated');
}

/**
 * Load SSL certificates if HTTPS is enabled
 */
function loadSSLCertificates() {
  if (!config.enableHttps) return null;

  console.log('🔐 Loading SSL certificates...');

  try {
    const sslOptions = {
      cert: fs.readFileSync(config.ssl.certPath),
      key: fs.readFileSync(config.ssl.keyPath)
    };

    if (config.ssl.caPath && fs.existsSync(config.ssl.caPath)) {
      sslOptions.ca = fs.readFileSync(config.ssl.caPath);
    }

    // Add security options
    sslOptions.minVersion = 'TLSv1.2';
    sslOptions.ciphers = [
      'ECDHE-RSA-AES128-GCM-SHA256',
      'ECDHE-ECDSA-AES128-GCM-SHA256',
      'ECDHE-RSA-AES256-GCM-SHA384',
      'ECDHE-ECDSA-AES256-GCM-SHA384',
      'DHE-RSA-AES128-GCM-SHA256',
      'DHE-DSS-AES128-GCM-SHA256',
      'kEDH+AESGCM',
      'ECDHE-RSA-AES128-SHA256',
      'ECDHE-ECDSA-AES128-SHA256',
      'ECDHE-RSA-AES128-SHA',
      'ECDHE-ECDSA-AES128-SHA',
      'ECDHE-RSA-AES256-SHA384',
      'ECDHE-ECDSA-AES256-SHA384',
      'ECDHE-RSA-AES256-SHA',
      'ECDHE-ECDSA-AES256-SHA',
      'DHE-RSA-AES128-SHA256',
      'DHE-RSA-AES128-SHA',
      'DHE-DSS-AES128-SHA256',
      'DHE-RSA-AES256-SHA256',
      'DHE-DSS-AES256-SHA',
      'DHE-RSA-AES256-SHA',
      'AES128-GCM-SHA256',
      'AES256-GCM-SHA384',
      'AES128-SHA256',
      'AES256-SHA256',
      'AES128-SHA',
      'AES256-SHA',
      'AES',
      'DES-CBC3-SHA'
    ].join(':');

    console.log('✅ SSL certificates loaded');
    return sslOptions;
  } catch (error) {
    console.error('❌ Failed to load SSL certificates:', error.message);
    throw error;
  }
}

/**
 * Create HTTP/HTTPS server
 */
function createServer(app, sslOptions) {
  let server;

  if (sslOptions) {
    server = https.createServer(sslOptions, app);
    console.log('🔐 HTTPS server created');
  } else {
    server = http.createServer(app);
    console.log('🌐 HTTP server created (HTTPS recommended for production)');
  }

  // Set timeouts for security
  server.setTimeout(30000); // 30 seconds
  server.keepAliveTimeout = 5000; // 5 seconds
  server.headersTimeout = 60000; // 60 seconds

  return server;
}

/**
 * Security headers middleware for HTTP to HTTPS redirect
 */
function createHttpsRedirectMiddleware() {
  return (req, res, next) => {
    if (!config.enableHttps || req.secure) {
      return next();
    }

    // Redirect HTTP to HTTPS
    const httpsHost = req.headers.host.replace(/:\d+$/, '');
    const httpsUrl = `https://${httpsHost}${req.originalUrl}`;

    // Use 301 for permanent redirect in production
    const statusCode = config.isProduction ? 301 : 302;

    res.redirect(statusCode, httpsUrl);
  };
}

/**
 * Graceful shutdown handler
 */
function setupGracefulShutdown(server) {
  const shutdown = (signal) => {
    console.log(`\n⚠️ Received ${signal}, shutting down gracefully...`);

    // Clear secrets from memory
    secretsManager.clear();

    server.close(() => {
      console.log('✅ Server closed');

      // Close database connections, etc.
      // databaseClient.close().then(() => {
      //   console.log('✅ Database connections closed');
      //   process.exit(0);
      // });

      process.exit(0);
    });

    // Force shutdown after timeout
    setTimeout(() => {
      console.error('❌ Could not close gracefully, forcing shutdown');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));
}

/**
 * Main application startup
 */
async function startApplication() {
  console.log('🚀 Starting secure application...');
  console.log(`📊 Environment: ${config.environment}`);
  console.log(`🔧 Port: ${config.port}`);

  try {
    // 1. Validate configuration
    validateConfig();

    // 2. Initialize secrets manager
    await secretsManager.initialize();

    // 3. Load SSL certificates if needed
    const sslOptions = loadSSLCertificates();

    // 4. Create Express application
    const app = require('./app-secure');

    // 5. Add HTTPS redirect middleware if needed
    if (config.enableHttps) {
      app.use(createHttpsRedirectMiddleware());
    }

    // 6. Create server
    const server = createServer(app, sslOptions);

    // 7. Setup graceful shutdown
    setupGracefulShutdown(server);

    // 8. Start listening
    server.listen(config.port, () => {
      const protocol = sslOptions ? 'https' : 'http';
      const host = process.env.HOST || 'localhost';

      console.log('\n' + '='.repeat(50));
      console.log(`✅ Application started successfully!`);
      console.log(`   URL: ${protocol}://${host}:${config.port}`);
      console.log(`   Environment: ${config.environment}`);
      console.log(`   Secrets loaded: ${secretsManager.getLoadedSecrets().length}`);
      console.log(`   HTTPS: ${sslOptions ? 'Enabled 🔐' : 'Disabled ⚠️'}`);
      console.log('='.repeat(50) + '\n');

      // Health check URL
      console.log(`📊 Health check: ${protocol}://${host}:${config.port}/health`);

      // Security status
      console.log('\n🔒 Security Status:');
      console.log(`   • Rate limiting: ${config.enableRateLimiting ? 'Enabled' : 'Disabled'}`);
      console.log(`   • CORS: ${config.enableCors ? 'Enabled' : 'Disabled'}`);
      console.log(`   • Security headers: ${config.enableSecurityHeaders ? 'Enabled' : 'Disabled'}`);

      // Development warnings
      if (config.isDevelopment) {
        console.log('\n⚠️  DEVELOPMENT MODE WARNINGS:');
        console.log('   • HTTP instead of HTTPS');
        console.log('   • Some security features may be relaxed');
        console.log('   • Do not use in production!');
      }
    });

    // Error handling for server
    server.on('error', (error) => {
      console.error('❌ Server error:', error);

      if (error.code === 'EADDRINUSE') {
        console.error(`   Port ${config.port} is already in use`);
        console.error('   Try changing the PORT environment variable');
      }

      process.exit(1);
    });

  } catch (error) {
    console.error('❌ Failed to start application:', error.message);
    console.error(error.stack);

    // Clear secrets on startup failure
    secretsManager.clear();

    process.exit(1);
  }
}

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('💥 Uncaught exception:', error);
  console.error(error.stack);

  // Clear secrets on crash
  secretsManager.clear();

  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('💥 Unhandled promise rejection:', reason);

  // Clear secrets on crash
  secretsManager.clear();

  process.exit(1);
});

// Start the application
startApplication();

/**
 * Secure Express.js application with proper secrets management
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, validationResult } = require('express-validator');

// Import secrets manager (singleton)
const secretsManager = require('./config/secrets');

const app = express();

// Note: dotenv is NOT required here - secrets are managed via secretsManager

// Security Middleware Configuration
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true
}));

// CORS configuration using secrets manager
app.use(cors({
  origin: secretsManager.get('ALLOWED_ORIGINS') ? 
    secretsManager.get('ALLOWED_ORIGINS').split(',') : [],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting with config from secrets
const limiter = rateLimit({
  windowMs: parseInt(secretsManager.get('RATE_LIMIT_WINDOW_MS') || '900000', 10), // 15 minutes default
  max: parseInt(secretsManager.get('RATE_LIMIT_MAX_REQUESTS') || '100', 10), // 100 requests default
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
