#!/usr/bin/env node

/**
 * Extract and redact credentials from .env.test file
 * Output: CSV format for rotation tracking spreadsheet
 */

const fs = require('fs');
const path = require('path');

function redactValue(value, showFirst = 4, showLast = 4) {
  if (!value || value.length <= (showFirst + showLast)) {
    return value || '';
  }
  return value.substring(0, showFirst) + '...' + value.substring(value.length - showLast);
}

function determinePriority(envVar) {
  const criticalPatterns = [
    /STRIPE_SECRET_KEY/,
    /DATABASE_URL/,
    /AWS_ACCESS_KEY_ID/,
    /AWS_SECRET_ACCESS_KEY/
  ];

  const highPatterns = [
    /ANTHROPIC_API_KEY/,
    /LOGFIRE_TOKEN/,
    /SECRET_KEY/,
    /PASSWORD/
  ];

  if (criticalPatterns.some(pattern => pattern.test(envVar))) {
    return 'CRITICAL';
  }
  if (highPatterns.some(pattern => pattern.test(envVar))) {
    return 'HIGH';
  }
  return 'MEDIUM';
}

function determineCredentialType(envVar) {
  if (envVar.includes('DATABASE_URL')) return 'Database Connection String';
  if (envVar.includes('AWS_ACCESS_KEY_ID')) return 'AWS Access Key';
  if (envVar.includes('AWS_SECRET_ACCESS_KEY')) return 'AWS Secret Key';
  if (envVar.includes('STRIPE_SECRET_KEY')) return 'Stripe Secret Key';
  if (envVar.includes('ANTHROPIC_API_KEY')) return 'Anthropic API Key';
  if (envVar.includes('LOGFIRE_TOKEN')) return 'Logfire Access Token';
  if (envVar.includes('API_KEY')) return 'API Key';
  if (envVar.includes('SECRET')) return 'Secret Key';
  if (envVar.includes('TOKEN')) return 'Access Token';
  if (envVar.includes('PASSWORD')) return 'Password';
  return 'Credential';
}

function main() {
  try {
    const envPath = path.join(__dirname, '.env.test');

    if (!fs.existsSync(envPath)) {
      console.error('❌ .env.test file not found');
      process.exit(1);
    }

    const content = fs.readFileSync(envPath, 'utf8');
    const lines = content.split('\n').filter(line => line.trim() && !line.trim().startsWith('#'));

    console.log('🔐 CREDENTIALS REQUIRING ROTATION');
    console.log('=' .repeat(60));
    console.log('Extracted from: .env.test');
    console.log('Date:', new Date().toISOString().split('T')[0]);
    console.log();

    // CSV header
    console.log('Variable Name,Redacted Value,Type,Priority,Service,Notes');

    for (const line of lines) {
      const [name, value] = line.split('=').map(part => part.trim());
      if (!name || !value) continue;

      const redacted = redactValue(value);
      const priority = determinePriority(name);
      const type = determineCredentialType(name);

      // Determine service
      let service = 'Unknown';
      if (name.includes('AWS')) service = 'AWS';
      if (name.includes('STRIPE')) service = 'Stripe';
      if (name.includes('ANTHROPIC')) service = 'Anthropic';
      if (name.includes('LOGFIRE')) service = 'Logfire';
      if (name.includes('DATABASE')) service = 'PostgreSQL';

      // Notes
      let notes = '';
      if (value.includes('CANARY')) notes = 'Contains CANARY string - likely test/detection value';
      if (value.includes('live')) notes = 'LIVE key detected - immediate rotation required';
      if (name.includes('SECRET') && name.includes('KEY')) notes = 'Secret key exposure - high risk';

      // CSV row
      console.log(`"${name}","${redacted}","${type}","${priority}","${service}","${notes}"`);
    }

    console.log();
    console.log('=' .repeat(60));
    console.log('📊 SUMMARY');
    console.log('=' .repeat(60));

    // Count by priority
    const counts = { CRITICAL: 0, HIGH: 0, MEDIUM: 0 };
    lines.forEach(line => {
      const [name] = line.split('=').map(part => part.trim());
      if (name) {
        const priority = determinePriority(name);
        counts[priority]++;
      }
    });

    console.log(`Total credentials found: ${lines.length}`);
    console.log(`CRITICAL priority: ${counts.CRITICAL} (rotate within 24h)`);
    console.log(`HIGH priority: ${counts.HIGH} (rotate within 72h)`);
    console.log(`MEDIUM priority: ${counts.MEDIUM}`);

    console.log();
    console.log('🚨 IMMEDIATE ACTIONS REQUIRED:');
    if (counts.CRITICAL > 0) {
      console.log(`1. Delete .env.test file immediately`);
      console.log(`2. Begin rotation of ${counts.CRITICAL} CRITICAL credentials`);
      console.log(`3. Update all references to use secure secrets manager`);
    }

    console.log();
    console.log('📋 Copy the CSV rows above into your rotation tracking spreadsheet');

  } catch (error) {
    console.error('Error processing .env.test:', error.message);
    process.exit(1);
  }
}

if (require.main === module) {
  main();
}

