  constructor() {
    this.secretsManager = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.secretsCache = {};
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.secretsCache[secretName]) {
      return this.secretsCache[secretName];
    }

    try {
      const data = await this.secretsManager
        .getSecretValue({ SecretId: secretName })
        .promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.secretsCache[secretName] = secret;
      return secret;

    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw error;
    }
  }

  async rotateSecrets(secretName) {
    // Trigger secret rotation
    await this.secretsManager
      .rotateSecret({ SecretId: secretName })
      .promise();

    // Clear cache for this secret
    delete this.secretsCache[secretName];
  }
}

module.exports = new AWSSecretsManager();
