// Secured Express.js application with comprehensive security measures
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const winston = require('winston');
const { body, query, param, validationResult } = require('express-validator');
const sanitize = require('express-sanitizer');

// Load environment variables
require('dotenv').config();

const app = express();

// ============= SECURITY SETUP =============

// 1. Security Headers with Helmet.js
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "'unsafe-inline'", "'unsafe-eval'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", "data:", "https:"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
    upgradeInsecureRequests: [],
  }
}));

// 2. CORS Configuration
const allowedOrigins = process.env.ALLOWED_ORIGINS ? 
  process.env.ALLOWED_ORIGINS.split(',') : 
  ['http://localhost:3000'];

const corsOptions = {
  origin: (origin, callback) => {
    if (!origin) return callback(null, true);
    if (allowedOrigins.includes(origin)) {
      return callback(null, true);
    }
    const msg = 'The CORS policy does not allow access from this origin.';
    return callback(new Error(msg), false);
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  credentials: true,
  maxAge: 86400
};

app.use(cors(corsOptions));

// 3. Rate Limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.',
});

app.use(generalLimiter);

// Stricter limiter for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 10, // 10 requests per hour
  message: 'Too many requests to this endpoint, please try again later.',
});

// 4. Logging Setup
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5
    }),
    new winston.transports.File({ 
      filename: 'logs/combined.log',
      maxsize: 5242880,
      maxFiles: 5
    }),
    new winston.transports.Console({
      format: winston.format.combine(
        winston.format.colorize(),
        winston.format.simple()
      )
    })
  ],
});

// HTTP request logging
app.use(morgan('combined', { 
  stream: { write: message => logger.info(message.trim()) }
}));

// Security event logging function
function logSecurityEvent(event, details, req) {
  logger.warn('Security Event', {
    event,
    details: sanitizeForLogging(details),
    timestamp: new Date().toISOString(),
    ip: req?.ip || 'unknown',
    userAgent: req?.get('User-Agent') || 'unknown',
    path: req?.originalUrl || 'unknown'
  });
}

// 5. Input sanitization
app.use(express.json({ limit: '10kb' }));
app.use(sanitize());

// Sanitization helper function
function sanitizeForLogging(data) {
  if (!data || typeof data !== 'object') return data;

  const sensitiveKeys = ['password', 'secret', 'token', 'key', 'authorization', 
                        'apikey', 'apisecret', 'apikeysecret', 'privatekey'];
  const sanitized = { ...data };

  Object.keys(sanitized).forEach(key => {
    const lowerKey = key.toLowerCase();
    sensitiveKeys.forEach(sensitiveKey => {
      if (lowerKey.includes(sensitiveKey)) {
        sanitized[key] = '[REDACTED]';
      }
    });
  });

  return sanitized;
}

// General input sanitization
function sanitizeInput(input) {
  if (typeof input === 'string') {
    // Remove potentially dangerous characters and script tags
    return input
      .replace(/<[^>]*>/g, '') // Remove HTML tags
      .replace(/javascript:/gi, '') // Remove javascript: protocol
      .replace(/data:/gi, '') // Remove data: protocol
      .replace(/on\w+=/gi, ''); // Remove event handlers
  }
  return input;
}

// ============= ROUTES WITH SECURITY =============

// Health check endpoint with basic validation
app.get('/health', 
  query('detailed').optional().isBoolean().withMessage('detailed must be boolean'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logSecurityEvent('Invalid input', { errors: errors.array() }, req);
      return res.status(400).json({ 
        status: 'error',
        errors: errors.array() 
      });
    }

    const detailed = req.query.detailed === 'true';

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      ...(detailed && {
        uptime: process.uptime(),
        memory: process.memoryUsage(),
        nodeVersion: process.version
      })
    });
  }
);

// Users endpoint with comprehensive input validation
app.get('/users', 
  strictLimiter, // Stricter rate limiting for user data
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
  query('search').optional().isString().trim().escape(),
  (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logSecurityEvent('Invalid user query', { errors: errors.array() }, req);
      return res.status(400).json({ 
        status: 'error',
        errors: errors.array() 
      });
    }

    // Sanitize inputs
    const limit = req.query.limit ? parseInt(sanitizeInput(req.query.limit)) : 10;
    const offset = req.query.offset ? parseInt(sanitizeInput(req.query.offset)) : 0;
    const search = req.query.search ? sanitizeInput(req.query.search) : null;

    // In a real application, you would query a database here
    // For demonstration, returning hardcoded data
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply search filter if provided (sanitized)
    if (search) {
      users = users.filter(user => 
        user.name.toLowerCase().includes(search.toLowerCase()) ||
        user.email.toLowerCase().includes(search.toLowerCase())
      );
    }

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: users.length,
        limit,
        offset,
        hasMore: offset + limit < users.length
      }
    });
  }
);

// Error handling middleware
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    path: req.originalUrl,
    method: req.method,
    ip: req.ip
  });

  logSecurityEvent('Unhandled error', { 
    error: err.message 
  }, req);

  res.status(500).json({ 
    status: 'error',
    message: 'An internal server error occurred'
  });
});

// 404 handler
app.use((req, res) => {
  logSecurityEvent('404 Not Found', { 
    path: req.originalUrl,
    method: req.method 
  }, req);

  res.status(404).json({ 
    status: 'error',
    message: 'Resource not found'
  });
});

// Validate required environment variables on startup
const requiredEnvVars = ['NODE_ENV'];
requiredEnvVars.forEach(envVar => {
  if (!process.env[envVar]) {
    logger.error(`Missing required environment variable: ${envVar}`);
    process.exit(1);
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running in ${process.env.NODE_ENV || 'development'} mode on port ${PORT}`);
});

module.exports = app;

