        if (value && value.includes('CANARY')) {
          errors.push(`CANARY value detected in ${key} - this appears to be a test secret`);
        }
        break;
    }
  });

  if (errors.length > 0) {
    const errorMessage = `Secret validation failed:\n${errors.join('\n')}`;
    logger.error(errorMessage, { errors });
    throw new Error(errorMessage);
  }

  logger.info('All secrets validated successfully');
}

/**
 * Mask sensitive secrets for logging
 */
function maskSensitiveSecrets(secrets) {
  const masked = { ...secrets };

  Object.keys(masked).forEach(key => {
    const config = REQUIRED_SECRETS[key];
    if (config?.sensitive && masked[key]) {
      const value = masked[key];
      // Show first 4 and last 4 characters for verification, mask the rest
      if (value.length > 8) {
        masked[key] = `${value.substring(0, 4)}...${value.substring(value.length - 4)}`;
      } else {
        masked[key] = '***';
      }
    }
  });

  return masked;
}

/**
 * Get a specific secret
 */
async function getSecret(key, defaultValue = null) {
  const secrets = await loadSecrets();
  return secrets[key] || defaultValue;
}

/**
 * Get all secrets (with sensitive values masked)
 */
async function getAllSecrets(masked = true) {
  const secrets = await loadSecrets();
  return masked ? maskSensitiveSecrets(secrets) : secrets;
}

/**
 * Check if a secret is present
 */
async function hasSecret(key) {
  const secrets = await loadSecrets();
  return key in secrets;
}

/**
 * Rotate a secret (placeholder for rotation logic)
 */
async function rotateSecret(key, newValue) {
  logger.warn(`Rotating secret: ${key}`);

  // In production, you'd update the secret in your secrets manager
  // and then update the cache

  const source = process.env.SECRETS_SOURCE || 'env';

  switch (source.toLowerCase()) {
    case 'aws':
      // Update in AWS Secrets Manager
      // await updateAWSSecret(key, newValue);
      break;

    case 'env':
      // Can't rotate environment variables at runtime
      logger.warn(`Cannot rotate environment variable ${key} at runtime`);
      break;
  }

  // Update cache
  if (secretsCache) {
    secretsCache[key] = newValue;
  }

  return true;
}

/**
 * Health check for secrets management
 */
async function healthCheck() {
  try {
    const secrets = await loadSecrets();
    const missing = Object.keys(REQUIRED_SECRETS).filter(
      key => REQUIRED_SECRETS[key].required && !secrets[key]
    );

    return {
      healthy: missing.length === 0,
      totalSecrets: Object.keys(secrets).length,
      missingRequired: missing,
      source: process.env.SECRETS_SOURCE || 'env',
      lastLoaded: lastLoadTime ? new Date(lastLoadTime).toISOString() : null,
      cacheAge: lastLoadTime ? Date.now() - lastLoadTime : null
    };
  } catch (error) {
    return {
      healthy: false,
      error: error.message,
      source: process.env.SECRETS_SOURCE || 'env'
    };
  }
}

module.exports = {
  loadSecrets,
  getSecret,
  getAllSecrets,
  hasSecret,
  rotateSecret,
  healthCheck,
  validateSecrets,
  REQUIRED_SECRETS
};

/**
 * Secure Logger Configuration
 * 
 * This logger ensures sensitive information is never logged.
 */

const winston = require('winston');
const { format } = winston;

// Regular expressions to detect sensitive patterns
const SENSITIVE_PATTERNS = [
  /password=["']?([^"'\s]+)["']?/gi,
  /secret=["']?([^"'\s]+)["']?/gi,
  /token=["']?([^"'\s]+)["']?/gi,
  /key=["']?([^"'\s]+)["']?/gi,
  /authorization=["']?([^"'\s]+)["']?/gi,
  /apikey=["']?([^"'\s]+)["']?/gi,
  /privatekey=["']?([^"'\s]+)["']?/gi,
  /database:.*@/gi,
  /postgres:\/\/[^:]+:[^@]+@/gi,
  /mysql:\/\/[^:]+:[^@]+@/gi,
  /mongodb:\/\/[^:]+:[^@]+@/gi,
  /\bAKIA[0-9A-Z]{16}\b/gi, // AWS Access Key ID
  /\bsk_(live|test)_[a-zA-Z0-9_]+\b/gi, // Stripe keys
];

// Custom format to redact sensitive information
const redactSensitive = format((info, opts) => {
  if (info.message && typeof info.message === 'string') {
    let message = info.message;
    SENSITIVE_PATTERNS.forEach(pattern => {
      message = message.replace(pattern, (match, capture) => {
        if (capture) {
          return match.replace(capture, '[REDACTED]');
        }
        return '[REDACTED]';
      });
    });
    info.message = message;
  }

  if (info.metadata) {
    const sanitizedMetadata = { ...info.metadata };
    Object.keys(sanitizedMetadata).forEach(key => {
      const value = sanitizedMetadata[key];
      if (typeof value === 'string') {
        SENSITIVE_PATTERNS.forEach(pattern => {
          if (pattern.test(value)) {
            sanitizedMetadata[key] = '[REDACTED]';
          }
        });
      }
    });
    info.metadata = sanitizedMetadata;
  }

  return info;
});

// Create the logger
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: format.combine(
    redactSensitive(),
    format.timestamp({
      format: 'YYYY-MM-DD HH:mm:ss'
    }),
    format.errors({ stack: true }),
    format.splat(),
    format.json()
  ),
  defaultMeta: { service: 'express-app' },
  transports: [
    // Write all logs with level `error` and below to `error.log`
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5
    }),

    // Write all logs with level `info` and below to `combined.log`
    new winston.transports.File({ 
      filename: 'logs/combined.log',
      maxsize: 5242880, // 5MB
      maxFiles: 5
    }),

    // Write security events to separate file
    new winston.transports.File({
      filename: 'logs/security.log',
      level: 'warn',
      maxsize: 5242880,
      maxFiles: 10,
      format: format.combine(
        format.timestamp(),
        format.json()
      )
    })
  ]
});

// Add console transport for non-production environments
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: format.combine(
      redactSensitive(),
      format.colorize(),
      format.simple()
    )
  }));
}

// Security logger helper
function logSecurityEvent(event, details = {}, request = null) {
  const logData = {
    event,
    details,
    timestamp: new Date().toISOString(),
    level: 'warn'
  };

  if (request) {
    logData.request = {
      ip: request.ip,
      userAgent: request.get('User-Agent'),
      method: request.method,
      path: request.path,
      query: request.query,
      headers: redactHeaders(request.headers)
    };
  }

  logger.warn('Security Event', logData);
}

// Helper to redact sensitive headers
function redactHeaders(headers) {
  const redacted = { ...headers };
  const sensitiveHeaders = [
    'authorization',
    'cookie',
    'x-api-key',
    'x-access-token',
    'x-auth-token'
  ];

  sensitiveHeaders.forEach(header => {
    if (redacted[header]) {
      redacted[header] = '[REDACTED]';
    }
    if (redacted[header.toLowerCase()]) {
      redacted[header.toLowerCase()] = '[REDACTED]';
    }
  });

  return redacted;
}

// Secret access logger
function logSecretAccess(secretName, action, context = {}) {
  logger.info('Secret Access', {
    secret: secretName,
    action,
    context: redactSensitiveContext(context),
    timestamp: new Date().toISOString()
  });
}

// Helper to redact sensitive context
function redactSensitiveContext(context) {
  const redacted = { ...context };
  const sensitiveKeys = ['value', 'secret', 'password', 'token', 'key'];

  Object.keys(redacted).forEach(key => {
    const lowerKey = key.toLowerCase();
    sensitiveKeys.forEach(sensitiveKey => {
      if (lowerKey.includes(sensitiveKey)) {
        redacted[key] = '[REDACTED]';
      }
    });
  });

  return redacted;
}

module.exports = {
  logger,
  logSecurityEvent,
  logSecretAccess,
  redactHeaders,
  redactSensitiveContext
};

#!/usr/bin/env node
/**
 * Secrets Validation Script
 * 
 * This script validates environment variables and secrets to prevent
 * the use of test/CANARY credentials in production.
 */

const fs = require('fs');
const path = require('path');

// Configuration
const CONFIG = {
  // Patterns to detect CANARY/test values
  CANARY_PATTERNS: [
    /CANARY/i,
    /test[-_]?secret/i,
    /fake[-_]?key/i,
    /dummy[-_]?token/i,
    /example[-_]?password/i,
  ],

  // Patterns to detect sensitive variables
  SENSITIVE_VAR_PATTERNS: [
    /_SECRET$/i,
    /_KEY$/i,
    /_TOKEN$/i,
    /_PASSWORD$/i,
    /DATABASE_URL/i,
    /AWS_/i,
    /API_?KEY/i,
  ],

  // Specific patterns for known credentials
  CREDENTIAL_PATTERNS: {
    AWS_ACCESS_KEY_ID: /^AKIA[0-9A-Z]{16}$/,
    AWS_SECRET_ACCESS_KEY: /^[A-Za-z0-9+/]{40}$/,
    STRIPE_SECRET_KEY: /^sk_(live|test)_[a-zA-Z0-9_]{24,}$/,
    DATABASE_URL: /^(postgres|mysql|mongodb):\/\//,
  }
};

// Colors for console output
const COLORS = {
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
  reset: '\x1b[0m',
  bold: '\x1b[1m'
};

// Helper function to redact secrets
function redactSecret(value) {
  if (!value || value.length < 8) return '***';
  return `${value.substring(0, 4)}...${value.substring(value.length - 4)}`;
}

// Check for CANARY values
function checkForCanaryValues() {
  console.log(`${COLORS.cyan}${COLORS.bold}🔍 Checking for CANARY/test values...${COLORS.reset}\n`);

  const env = process.env;
  const issues = [];
  const warnings = [];

  Object.keys(env).forEach(key => {
    const value = env[key];

    if (!value) return;

    // Check if this looks like a sensitive variable
    const isSensitive = CONFIG.SENSITIVE_VAR_PATTERNS.some(pattern => pattern.test(key));

    if (isSensitive) {
      // Check for CANARY patterns
      CONFIG.CANARY_PATTERNS.forEach(pattern => {
        if (pattern.test(value)) {
          issues.push({
            type: 'CANARY_VALUE',
            variable: key,
            value: redactSecret(value),
            fullValue: value,
            pattern: pattern.toString(),
            severity: 'CRITICAL'
          });
        }
      });

      // Check format if we have a specific pattern for this variable
      const specificPattern = CONFIG.CREDENTIAL_PATTERNS[key];
      if (specificPattern && !specificPattern.test(value)) {
        warnings.push({
          type: 'INVALID_FORMAT',
          variable: key,
          value: redactSecret(value),
          expectedPattern: specificPattern.toString(),
          severity: 'WARNING'
        });
      }
    }
  });

  return { issues, warnings };
}

// Check for .env files
function checkEnvFiles() {
  console.log(`${COLORS.cyan}${COLORS.bold}📁 Checking for environment files...${COLORS.reset}\n`);

  const files = [];
  const currentDir = process.cwd();

  try {
    const allFiles = fs.readdirSync(currentDir);
    const envFiles = allFiles.filter(file => 
      file.startsWith('.env') && !file.endsWith('.example')
    );

    envFiles.forEach(file => {
      const filePath = path.join(currentDir, file);
      const stats = fs.statSync(filePath);

      files.push({
        name: file,
        path: filePath,
        size: stats.size,
        modified: stats.mtime
      });
    });
  } catch (error) {
    console.error(`${COLORS.red}Error reading directory: ${error.message}${COLORS.reset}`);
  }

  return files;
}

// Analyze .env file contents
function analyzeEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    const secrets = [];
    lines.forEach((line, index) => {
      line = line.trim();

      // Skip comments and empty lines
      if (!line || line.startsWith('#')) return;

      const match = line.match(/^([A-Z_][A-Z0-9_]*)=(.*)$/);
      if (match) {
        const [, key, value] = match;

        // Check if this looks sensitive
        const isSensitive = CONFIG.SENSITIVE_VAR_PATTERNS.some(pattern => pattern.test(key));

        if (isSensitive) {
          secrets.push({
            key,
            value: redactSecret(value),
            fullValue: value,
            line: index + 1,
            isSensitive: true
          });
        }
      }
    });

    return secrets;
  } catch (error) {
    console.error(`${COLORS.red}Error reading file ${filePath}: ${error.message}${COLORS.reset}`);
    return [];
  }
}

// Generate report
function generateReport(canaryCheck, envFiles) {
  console.log(`${COLORS.bold}${COLORS.cyan}📊 SECURITY VALIDATION REPORT${COLORS.reset}\n`);

  const { issues, warnings } = canaryCheck;

  // Critical Issues
  if (issues.length > 0) {
    console.log(`${COLORS.red}${COLORS.bold}⚠️  CRITICAL ISSUES FOUND:${COLORS.reset}`);
    issues.forEach(issue => {
      console.log(`${COLORS.red}  • ${issue.variable}: ${issue.type}`);
      console.log(`    Value: ${issue.value}`);
      console.log(`    Pattern matched: ${issue.pattern}`);
      console.log(`    Severity: ${issue.severity}${COLORS.reset}\n`);
    });
  } else {
    console.log(`${COLORS.green}✅ No CANARY values detected in environment variables${COLORS.reset}\n`);
  }

  // Warnings
  if (warnings.length > 0) {
    console.log(`${COLORS.yellow}${COLORS.bold}⚠️  WARNINGS:${COLORS.reset}`);
    warnings.forEach(warning => {
      console.log(`${COLORS.yellow}  • ${warning.variable}: ${warning.type}`);
      console.log(`    Value: ${warning.value}`);
      console.log(`    Expected pattern: ${warning.expectedPattern}${COLORS.reset}\n`);
    });
  }

  // Environment files
  if (envFiles.length > 0) {
    console.log(`${COLORS.yellow}${COLORS.bold}📄 ENVIRONMENT FILES FOUND:${COLORS.reset}`);
    envFiles.forEach(file => {
      console.log(`${COLORS.yellow}  • ${file.name}`);
      console.log(`    Size: ${file.size} bytes`);
      console.log(`    Modified: ${file.modified.toISOString()}${COLORS.reset}`);

      // Analyze file contents
      const secrets = analyzeEnvFile(file.path);
      if (secrets.length > 0) {
        console.log(`    ${COLORS.red}Sensitive variables found in file:${COLORS.reset}`);
        secrets.forEach(secret => {
          console.log(`      - ${secret.key}: ${secret.value} (line ${secret.line})`);
        });
      }
      console.log('');
    });
  } else {
    console.log(`${COLORS.green}✅ No .env files found (excluding .env.example)${COLORS.reset}\n`);
  }

  // Summary
  console.log(`${COLORS.bold}${COLORS.cyan}📈 SUMMARY${COLORS.reset}`);
  console.log(`Critical Issues: ${issues.length}`);
  console.log(`Warnings: ${warnings.length}`);
  console.log(`Environment Files: ${envFiles.length}`);

  // Recommendations
  console.log(`\n${COLORS.bold}${COLORS.cyan}💡 RECOMMENDATIONS${COLORS.reset}`);

  if (issues.length > 0) {
    console.log(`${COLORS.red}1. IMMEDIATE ACTION: Rotate all CANARY credentials${COLORS.reset}`);
    console.log(`${COLORS.red}2. Remove .env files from version control${COLORS.reset}`);
    console.log(`${COLORS.red}3. Implement secrets manager${COLORS.reset}`);
  }

  if (envFiles.length > 0) {
    console.log(`${COLORS.yellow}4. Securely store environment files${COLORS.reset}`);
    console.log(`${COLORS.yellow}5. Add .env* to .gitignore${COLORS.reset}`);
  }

  console.log(`${COLORS.green}6. Run this validation in CI/CD pipeline${COLORS.reset}`);
  console.log(`${COLORS.green}7. Implement regular secret rotation${COLORS.reset}`);

  // Exit code based on findings
  if (issues.length > 0) {
    console.log(`\n${COLORS.red}${COLORS.bold}❌ Validation failed - critical issues found${COLORS.reset}`);
    process.exit(1);
  } else {
    console.log(`\n${COLORS.green}${COLORS.bold}✅ Validation passed${COLORS.reset}`);
    process.exit(0);
  }
}

// Main function
function main() {
  console.log(`${COLORS.bold}${COLORS.cyan}🔒 Secrets Validation Script${COLORS.reset}`);
  console.log(`${COLORS.cyan}================================${COLORS.reset}\n`);

  // Check current environment
  const canaryCheck = checkForCanaryValues();

  // Check for .env files
  const envFiles = checkEnvFiles();

  // Generate report
  generateReport(canaryCheck, envFiles);
}

// Run the script
if (require.main === module) {
  main();
}

module.exports = {
  checkForCanaryValues,
  checkEnvFiles,
  analyzeEnvFile,
  generateReport
};

