// Secure Express.js application with security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan'); // For logging

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes'
  },
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req) => {
    // Use IP address for rate limiting
    return req.ip;
  }
});

// Apply rate limiting to all routes
app.use(limiter);

// 3. CORS configuration
const corsOptions = {
  origin: (origin, callback) => {
    // Define allowed origins
    const allowedOrigins = process.env.NODE_ENV === 'production'
      ? ['https://yourdomain.com']
      : ['http://localhost:3000', 'http://localhost:8080'];

    // Check if origin is allowed
    if (!origin || allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS']
};

app.use(cors(corsOptions));

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Request logging (in production, use structured logging)
app.use(morgan('combined', {
  skip: (req, res) => req.path === '/health' // Skip logging health checks
}));

// ========== ROUTES WITH SECURITY MEASURES ==========

// Health endpoint with minimal information disclosure
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok',
    timestamp: new Date().toISOString(),
    // Don't expose internal details like uptime, memory usage in production
    environment: process.env.NODE_ENV || 'development'
  });
});

// Users endpoint with input validation and sanitization
app.get('/users', [
  // Input validation
  query('limit').optional().isInt({ min: 1, max: 50 }).withMessage('Limit must be between 1 and 50'),
  query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
  query('sort').optional().isIn(['name', 'id']).withMessage('Sort must be either "name" or "id"')
], (req, res) => {
  // Check validation results
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array().map(err => ({
        param: err.param,
        msg: err.msg,
        value: err.value
      }))
    });
  }

  // Simulated user data with sanitized output
  const users = [
    { 
      id: 1, 
      name: 'Alice',
      // Never expose email unless explicitly required and authorized
      // email: 'alice@example.com' 
    },
    { 
      id: 2, 
      name: 'Bob',
      // email: 'bob@example.com'
    },
  ];

  // Apply sorting if requested
  const { sort } = req.query;
  if (sort === 'name') {
    users.sort((a, b) => a.name.localeCompare(b.name));
  }

  // Apply pagination if requested
  const limit = parseInt(req.query.limit) || 10;
  const offset = parseInt(req.query.offset) || 0;
  const paginatedUsers = users.slice(offset, offset + limit);

  // Return sanitized response
  res.json({
    data: paginatedUsers,
    meta: {
      total: users.length,
      limit,
      offset,
      hasMore: offset + limit < users.length
    }
  });
});

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Error handler - prevents stack trace exposure
app.use((err, req, res, next) => {
  console.error('Error:', err.message);
  console.error('Stack:', err.stack);

  const statusCode = err.status || 500;
  const response = {
    error: 'Internal server error'
  };

  // Only include details in development
  if (process.env.NODE_ENV === 'development') {
    response.message = err.message;
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ========== SERVER CONFIGURATION ==========

const PORT = process.env.PORT || 3000;

// Security: Don't expose server info in headers
app.disable('x-powered-by');

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
const shutdown = () => {
  console.log('Shutting down server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;

// Security audit script for Express.js applications
// Run with: node security_audit.js

const fs = require('fs');
const path = require('path');

class SecurityAuditor {
  constructor() {
    this.checks = [];
    this.results = [];
  }

  addCheck(name, checkFn) {
    this.checks.push({ name, checkFn });
  }

  async runAudit() {
    console.log('🔒 Running Security Audit...\n');

    for (const check of this.checks) {
      try {
        const result = await check.checkFn();
        this.results.push({
          check: check.name,
          ...result
        });

        const status = result.passed ? '✅' : '❌';
        console.log(`${status} ${check.name}`);
        if (!result.passed && result.details) {
          console.log(`   Details: ${result.details}`);
        }
      } catch (error) {
        console.log(`❌ ${check.name} - Error: ${error.message}`);
      }
    }

    this.printSummary();
  }

  printSummary() {
    console.log('\n📊 Audit Summary:');
    console.log('='.repeat(50));

    const passed = this.results.filter(r => r.passed).length;
    const failed = this.results.length - passed;

    console.log(`Total Checks: ${this.results.length}`);
    console.log(`Passed: ${passed}`);
    console.log(`Failed: ${failed}`);

    if (failed > 0) {
      console.log('\n⚠️  Failed Checks:');
      this.results.filter(r => !r.passed).forEach(r => {
        console.log(`  • ${r.check}`);
        if (r.recommendation) {
          console.log(`    Recommendation: ${r.recommendation}`);
        }
      });
    }
  }
}

// Create auditor instance
const auditor = new SecurityAuditor();

// Security checks
auditor.addCheck('Environment Variables', () => {
  const envFiles = fs.readdirSync('.').filter(f => f.startsWith('.env'));

  const issues = [];

  envFiles.forEach(file => {
    const content = fs.readFileSync(file, 'utf8');

    // Check for hardcoded secrets
    const secretPatterns = [
      /password\s*=\s*\S+/i,
      /secret\s*=\s*\S+/i,
      /key\s*=\s*\S+/i,
      /token\s*=\s*\S+/i,
      /aws_access_key_id\s*=\s*\S+/i,
      /aws_secret_access_key\s*=\s*\S+/i,
      /database_url\s*=\s*\S+/i
    ];

    secretPatterns.forEach(pattern => {
      if (pattern.test(content)) {
        const matches = content.match(pattern);
        matches?.forEach(match => {
          if (!match.toLowerCase().includes('placeholder') && 
              !match.toLowerCase().includes('example') &&
              !match.toLowerCase().includes('your_')) {
            issues.push(`${file}: Potential hardcoded secret found: ${match.substring(0, 50)}...`);
          }
        });
      }
    });

    // Check for .env in version control
    const gitignore = fs.existsSync('.gitignore') ? fs.readFileSync('.gitignore', 'utf8') : '';
    if (!gitignore.includes('.env')) {
      issues.push(`.env files not ignored in .gitignore`);
    }
  });

  return {
    passed: issues.length === 0,
    details: issues.length > 0 ? issues.join('; ') : 'No issues found',
    recommendation: issues.length > 0 
      ? 'Remove hardcoded secrets, use .env.example for templates, ensure .env is in .gitignore'
      : null
  };
});

auditor.addCheck('Dependency Versions', () => {
  if (!fs.existsSync('package.json')) {
    return { passed: false, details: 'package.json not found' };
  }

  const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
  const vulnerabilities = [];

  // Check for known vulnerable versions (example checks)
  const vulnerableDeps = {
    'express': { min: '4.17.0', reason: 'Security patches' },
    'helmet': { min: '4.0.0', reason: 'CSP improvements' }
  };

  Object.entries(vulnerableDeps).forEach(([dep, info]) => {
    if (pkg.dependencies?.[dep]) {
      const version = pkg.dependencies[dep];
      if (version.startsWith('^') || version.startsWith('~')) {
        // Could add more sophisticated version checking here
        console.log(`   Note: Version range for ${dep}: ${version}`);
      }
    }
  });

  return {
    passed: vulnerabilities.length === 0,
    details: vulnerabilities.length > 0 ? vulnerabilities.join('; ') : 'No known vulnerable versions detected',
    recommendation: 'Run "npm audit" regularly and update dependencies'
  };
});

auditor.addCheck('Security Headers', () => {
  const appFile = fs.existsSync('app.js') ? 'app.js' : 
                   fs.existsSync('app_secure.js') ? 'app_secure.js' : null;

  if (!appFile) {
    return { passed: false, details: 'No app file found' };
  }

  const content = fs.readFileSync(appFile, 'utf8');
  const checks = [
    { name: 'Helmet middleware', pattern: /helmet/i, required: true },
    { name: 'CORS configuration', pattern: /cors/i, required: true },
    { name: 'Rate limiting', pattern: /rate.*limit/i, required: true },
    { name: 'x-powered-by disabled', pattern: /disable.*['"]x-powered-by['"]/i, required: true },
    { name: 'Input validation', pattern: /express-validator/i, required: true }
  ];

  const missing = checks
    .filter(check => check.required && !check.pattern.test(content))
    .map(check => check.name);

  return {
    passed: missing.length === 0,
    details: missing.length > 0 ? `Missing: ${missing.join(', ')}` : 'All security headers configured',
    recommendation: missing.length > 0 
      ? 'Add missing security middleware as shown in app_secure.js'
      : null
  };
});

auditor.addCheck('File Permissions', () => {
  const criticalFiles = [
    '.env',
    '.env.production',
    'package.json',
    'app.js'
  ];

  const issues = [];

  criticalFiles.forEach(file => {
    if (fs.existsSync(file)) {
      const stats = fs.statSync(file);
      // Check if file is world-writable
      if (stats.mode & 0o002) {
        issues.push(`${file} is world-writable`);
      }
    }
  });

  return {
    passed: issues.length === 0,
    details: issues.length > 0 ? issues.join('; ') : 'File permissions are secure',
    recommendation: issues.length > 0 
      ? 'Set appropriate file permissions (e.g., chmod 600 for .env files)'
      : null
  };
});

auditor.addCheck('Error Handling', () => {
  const appFile = fs.existsSync('app.js') ? 'app.js' : 
                   fs.existsSync('app_secure.js') ? 'app_secure.js' : null;

  if (!appFile) {
    return { passed: false, details: 'No app file found' };
  }

  const content = fs.readFileSync(appFile, 'utf8');

  const checks = [
    { name: 'Error middleware', pattern: /app\.use.*err.*req.*res.*next/i, required: true },
    { name: 'Stack trace protection', pattern: /process\.env\.NODE_ENV.*development.*stack/i, required: true },
    { name: '404 handler', pattern: /404.*handler|app\.use.*404/i, required: true }
  ];

  const missing = checks
    .filter(check => check.required && !check.pattern.test(content))
    .map(check => check.name);

  return {
    passed: missing.length === 0,
    details: missing.length > 0 ? `Missing: ${missing.join(', ')}` : 'Proper error handling implemented',
    recommendation: missing.length > 0 
      ? 'Implement comprehensive error handling to prevent information disclosure'
      : null
  };
});

// Run the audit
auditor.runAudit().catch(console.error);

