         if (!this.validateSecret(key, value)) {
           throw new Error(`Invalid secret for ${key}`);
         }
         this.secrets.set(key, value);
       }

       this.validated = true;
     }

     validateSecret(key, value) {
       if (!value) return false;

       // Reject placeholder values in production
       if (process.env.NODE_ENV === 'production') {
         const placeholderPatterns = [
           /CANARY/i,
           /DUMMY/i,
           /EXAMPLE/i,
           /TEST_/i,
           /fake/i,
