5. **Migrate to Cloud Secret Manager**
   ```javascript
   // Using AWS Secrets Manager
   const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

   class CloudSecretManager {
     constructor() {
       this.client = new SecretsManager({
         region: process.env.AWS_REGION
       });
       this.cache = new Map();
     }

     async getSecret(secretName) {
       if (this.cache.has(secretName)) {
         return this.cache.get(secretName);
       }

       try {
         const response = await this.client.getSecretValue({
           SecretId: secretName
         });

         let secret;
         if ('SecretString' in response) {
           secret = JSON.parse(response.SecretString);
         } else {
           secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
         }

         this.cache.set(secretName, secret);
         return secret;
       } catch (error) {
         console.error(`Error retrieving secret ${secretName}:`, error);
         throw error;
       }
     }

     async rotateSecret(secretName) {
       this.cache.delete(secretName);
       return this.getSecret(secretName);
     }
   }
   ```

