   ```javascript
   // Using encrypted .env files with key rotation
   const crypto = require('crypto');
   const fs = require('fs');

   class EncryptedEnv {
     constructor(encryptionKey) {
       this.key = crypto.createHash('sha256')
         .update(encryptionKey)
         .digest();
       this.iv = crypto.randomBytes(16);
     }

     encrypt(text) {
       const cipher = crypto.createCipheriv('aes-256-gcm', this.key, this.iv);
       let encrypted = cipher.update(text, 'utf8', 'hex');
       encrypted += cipher.final('hex');
       const authTag = cipher.getAuthTag();
       return {
         iv: this.iv.toString('hex'),
         encrypted,
         authTag: authTag.toString('hex')
       };
     }

     decrypt(encryptedData) {
       const decipher = crypto.createDecipheriv(
         'aes-256-gcm',
         this.key,
         Buffer.from(encryptedData.iv, 'hex')
       );
       decipher.setAuthTag(Buffer.from(encryptedData.authTag, 'hex'));
       let decrypted = decipher.update(encryptedData.encrypted, 'hex', 'utf8');
       decrypted += decipher.final('utf8');
       return decrypted;
     }

     saveEncryptedEnv(data, filePath) {
       const encrypted = this.encrypt(JSON.stringify(data));
       fs.writeFileSync(filePath, JSON.stringify(encrypted, null, 2));
     }

     loadEncryptedEnv(filePath) {
       const encrypted = JSON.parse(fs.readFileSync(filePath, 'utf8'));
       return JSON.parse(this.decrypt(encrypted));
     }
   }
