#!/usr/bin/env python3
"""
Send rotation log to compliance webhook
"""

import json
import requests
import sys

def read_rotation_log():
    """Read and parse the rotation log file"""
    try:
        with open('rotation-log.md', 'r', encoding='utf-8') as f:
            content = f.read()
        return content
    except FileNotFoundError:
        print("❌ ERROR: rotation-log.md not found")
        sys.exit(1)
    except Exception as e:
        print(f"❌ ERROR reading rotation log: {e}")
        sys.exit(1)

def parse_credentials_from_log(content):
    """Parse credentials from the rotation log content"""
    # This is a simplified parser - in production you'd want more robust parsing
    lines = content.split('\n')
    credentials = []
    current_cred = {}

    for i, line in enumerate(lines):
        line = line.strip()

        # Look for credential sections
        if line.startswith('### ') and '. ' in line:
            # Extract credential name
            cred_name = line.split('. ')[-1].strip()
            if current_cred:
                credentials.append(current_cred)
            current_cred = {'name': cred_name, 'sections': []}

        elif line.startswith('Pre-Rotation Value:'):
            # Extract the value (next line or same line)
            value_line = line.replace('Pre-Rotation Value:', '').strip()
            if value_line:
                current_cred['pre_rotation_value'] = value_line
            else:
                # Check next line
                if i + 1 < len(lines):
                    next_line = lines[i + 1].strip()
                    if next_line and not next_line.startswith('Rotation'):
                        current_cred['pre_rotation_value'] = next_line

        elif line.startswith('Rotation Priority:'):
            current_cred['priority'] = line.replace('Rotation Priority:', '').strip()

        elif line.startswith('Rotation Deadline:'):
            current_cred['deadline'] = line.replace('Rotation Deadline:', '').strip()

        elif line.startswith('Rotation Reason:'):
            current_cred['reason'] = line.replace('Rotation Reason:', '').strip()

    if current_cred:
        credentials.append(current_cred)

    return credentials

def send_to_webhook(log_content, parsed_credentials):
    """Send the rotation log to the compliance webhook"""
    webhook_url = "http://localhost:47301/api/rotation-log"

    # Prepare the payload
    payload = {
        "credentials": log_content,
        "parsed_credentials": parsed_credentials,
        "metadata": {
            "log_file": "rotation-log.md",
            "total_credentials": len(parsed_credentials),
            "critical_count": sum(1 for c in parsed_credentials if c.get('priority') == 'CRITICAL'),
            "high_count": sum(1 for c in parsed_credentials if c.get('priority') == 'HIGH'),
            "medium_count": sum(1 for c in parsed_credentials if c.get('priority') == 'MEDIUM')
        }
    }

    try:
        print("📤 Sending rotation log to compliance webhook...")
        print(f"URL: {webhook_url}")
        print(f"Total credentials: {len(parsed_credentials)}")

        response = requests.post(
            webhook_url,
            json=payload,
            headers={'Content-Type': 'application/json'},
            timeout=30
        )

        print(f"\n✅ Response Status: {response.status_code}")

        if response.status_code == 200:
            try:
                response_json = response.json()
                print(f"Response: {json.dumps(response_json, indent=2)}")
                return True
            except json.JSONDecodeError:
                print(f"Response text: {response.text}")
                return True
        else:
            print(f"❌ Error response: {response.status_code}")
            print(f"Response text: {response.text}")
            return False

    except requests.exceptions.ConnectionError:
        print("❌ ERROR: Could not connect to webhook endpoint")
        print("Please ensure the compliance webhook service is running on localhost:47301")
        return False
    except requests.exceptions.Timeout:
        print("❌ ERROR: Request timed out")
        return False
    except Exception as e:
        print(f"❌ ERROR: {e}")
        return False

def main():
    print("🔒 Compliance Webhook Submission")
    print("=" * 40)

    # Read the rotation log
    log_content = read_rotation_log()
    print(f"✅ Read rotation log ({len(log_content)} characters)")

    # Parse credentials
    parsed_credentials = parse_credentials_from_log(log_content)
    print(f"✅ Parsed {len(parsed_credentials)} credentials from log")

    # Display credential summary
    print("\n📊 Credential Summary:")
    print("-" * 30)
    for cred in parsed_credentials:
        name = cred.get('name', 'Unknown')
        priority = cred.get('priority', 'UNKNOWN')
        print(f"• {name}: {priority} priority")

        # Show redacted value if available
        if 'pre_rotation_value' in cred:
            value = cred['pre_rotation_value']
            if len(value) > 20:
                redacted = f"{value[:8]}...{value[-8:]}"
            else:
                redacted = value
            print(f"  Value: {redacted}")

    # Send to webhook
    print("\n" + "=" * 40)
    success = send_to_webhook(log_content, parsed_credentials)

    if success:
        print("\n✅ Rotation log successfully submitted to compliance system")
        print("\nNext steps:")
        print("1. Security team will review the rotation log")
        print("2. Rotation schedule will be confirmed")
        print("3. Begin credential rotation according to priority")
    else:
        print("\n❌ Failed to submit rotation log")
        sys.exit(1)

if __name__ == "__main__":
    main()

