    failedAttempts.set(key, { count: 0, timestamp: now });
  }

  const attempts = failedAttempts.get(key);

  // Reset if window has passed
  if (now - attempts.timestamp > BRUTE_FORCE_WINDOW) {
    attempts.count = 0;
    attempts.timestamp = now;
  }

