if (error) {
  throw new Error(`Environment validation error: ${error.message}`);
}

// Secure configuration loader
class SecureConfig {
  constructor() {
    this.config = {};
    this.secrets = new Map();
  }

  // Load and validate configuration
  load() {
    // Store sensitive values securely
    this.secrets.set('JWT_SECRET', envVars.JWT_SECRET);
    this.secrets.set('ENCRYPTION_KEY', envVars.ENCRYPTION_KEY);
    this.secrets.set('DATABASE_URL', envVars.DATABASE_URL);

    // Public configuration
    this.config = {
      nodeEnv: envVars.NODE_ENV,
      port: envVars.PORT,
      database: {
        maxConnections: envVars.DATABASE_MAX_CONNECTIONS,
        useSSL: envVars.NODE_ENV === 'production'
      },
      security: {
        jwtExpiry: '1h',
        bcryptRounds: 12,
        rateLimit: {
          window: envVars.API_RATE_LIMIT_WINDOW,
          max: envVars.API_RATE_LIMIT_MAX
        }
      },
      cors: {
        origins: envVars.ALLOWED_ORIGINS ? 
          envVars.ALLOWED_ORIGINS.split(',') : 
          envVars.NODE_ENV === 'production' ? [] : ['http://localhost:3000']
      },
      logging: {
        level: envVars.LOG_LEVEL,
        dir: 'logs'
      }
    };

    // Validate production-specific settings
    if (envVars.NODE_ENV === 'production') {
      this.validateProductionConfig();
    }
  }

  validateProductionConfig() {
    const requiredInProduction = [
      'JWT_SECRET',
      'ENCRYPTION_KEY',
      'DATABASE_URL'
    ];

    for (const key of requiredInProduction) {
      if (!envVars[key]) {
        throw new Error(`${key} is required in production environment`);
      }
    }

    // Validate JWT secret strength
    if (envVars.JWT_SECRET.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters in production');
    }

    // Validate encryption key
    if (!/^[A-Za-z0-9+/=]{32,}$/.test(envVars.ENCRYPTION_KEY)) {
      throw new Error('ENCRYPTION_KEY must be base64 encoded and at least 32 characters');
    }
  }

  // Get secret (logs access for auditing)
  getSecret(key) {
    console.log(`[SECRET ACCESS] ${key} accessed at ${new Date().toISOString()}`);
    const value = this.secrets.get(key);

    if (!value) {
      throw new Error(`Secret ${key} not found`);
    }

    return value;
  }

  // Get public config
  get(key) {
    return this.config[key];
  }

  // Check if production
  isProduction() {
    return envVars.NODE_ENV === 'production';
  }
}

