class SecretsManager {
  constructor() {
    this.cacheDuration = 5 * 60 * 1000; // 5 minutes
    this.secretsCache = new cache.Cache();

    // Initialize AWS client
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1',
      // AWS credentials from environment or IAM role
    });
  }

  /**
   * Get secret value from AWS Secrets Manager with caching
   */
  async getSecret(secretId, forceRefresh = false) {
    const cacheKey = `secret:${secretId}`;

    // Check cache first
    if (!forceRefresh) {
      const cached = this.secretsCache.get(cacheKey);
      if (cached) {
        console.log(`Cache hit for secret: ${secretId}`);
        return cached;
      }
    }

    try {
      console.log(`Fetching secret: ${secretId}`);
      const data = await this.client.getSecretValue({ SecretId: secretId }).promise();

      let secretValue;
      if ('SecretString' in data) {
        secretValue = JSON.parse(data.SecretString);
      } else {
        // For binary secrets
        secretValue = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.secretsCache.put(cacheKey, secretValue, this.cacheDuration);

      return secretValue;
    } catch (error) {
      console.error(`Error fetching secret ${secretId}:`, error);
      throw error;
    }
  }

  /**
   * Rotate secret (admin function)
   */
  async rotateSecret(secretId) {
    try {
      await this.client.rotateSecret({ SecretId: secretId }).promise();
      console.log(`Initiated rotation for secret: ${secretId}`);

      // Invalidate cache
      this.secretsCache.del(`secret:${secretId}`);
    } catch (error) {
      console.error(`Error rotating secret ${secretId}:`, error);
      throw error;
    }
  }

  /**
   * List all secrets (for audit)
   */
  async listSecrets() {
    try {
      const data = await this.client.listSecrets().promise();
      return data.SecretList.map(secret => ({
        name: secret.Name,
        description: secret.Description,
        lastChanged: secret.LastChangedDate,
        rotationEnabled: secret.RotationEnabled || false
      }));
    } catch (error) {
      console.error('Error listing secrets:', error);
      throw error;
    }
  }
}

