/**
 * Production-ready Secrets Manager
 * Supports AWS Secrets Manager, Hashicorp Vault, and Azure Key Vault
 */

const crypto = require('crypto');
const cache = require('memory-cache');
const winston = require('winston');

class SecretsManager {
  constructor(options = {}) {
    this.options = {
      provider: process.env.SECRETS_PROVIDER || 'aws', // aws, vault, azure, local
      cacheDuration: 5 * 60 * 1000, // 5 minutes
      encryptionEnabled: true,
      validateOnLoad: true,
      ...options
    };

    this.cache = new cache.Cache();
    this.logger = winston.createLogger({
      level: 'info',
      format: winston.format.combine(
        winston.format.timestamp(),
        winston.format.json()
      ),
      transports: [
        new winston.transports.Console(),
        new winston.transports.File({ 
          filename: 'logs/secrets-audit.log',
          level: 'audit'
        })
      ]
    });

    this.initializeProvider();
  }

  /**
   * Initialize secrets provider based on configuration
   */
  initializeProvider() {
    switch (this.options.provider) {
      case 'aws':
        this.initAWS();
        break;
      case 'vault':
        this.initVault();
        break;
      case 'azure':
        this.initAzure();
        break;
      case 'local':
        this.initLocal();
        break;
      default:
        throw new Error(`Unsupported secrets provider: ${this.options.provider}`);
    }
  }

  /**
   * Initialize AWS Secrets Manager
   */
  initAWS() {
    const AWS = require('aws-sdk');

    // AWS credentials from environment, EC2 role, or ECS task role
    this.provider = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1',
      maxRetries: 3,
      retryDelayOptions: { base: 300 }
    });

    this.getSecretFn = async (secretId) => {
      const data = await this.provider.getSecretValue({ SecretId: secretId }).promise();
      return data.SecretString ? JSON.parse(data.SecretString) : data.SecretBinary;
    };
  }

  /**
   * Initialize Hashicorp Vault
   */
  initVault() {
    const NodeVault = require('node-vault');

    this.provider = NodeVault({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN,
      apiVersion: 'v1'
    });

    this.getSecretFn = async (path) => {
      const secret = await this.provider.read(path);
      return secret.data;
    };
  }

  /**
   * Initialize Azure Key Vault
   */
  initAzure() {
    const { SecretClient } = require('@azure/keyvault-secrets');
    const { DefaultAzureCredential } = require('@azure/identity');

    const credential = new DefaultAzureCredential();
    this.provider = new SecretClient(
      process.env.AZURE_KEY_VAULT_URL,
      credential
    );

    this.getSecretFn = async (name) => {
      const secret = await this.provider.getSecret(name);
      return secret.value;
    };
  }

  /**
   * Initialize local provider (development only)
   */
  initLocal() {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('Local secrets provider not allowed in production');
    }

    console.warn('⚠️ WARNING: Using local secrets provider - NOT FOR PRODUCTION');

    // Default development secrets
    this.devSecrets = {
      DATABASE_URL: 'postgres://localhost:5432/dev',
      JWT_SECRET: 'dev-jwt-secret-change-in-production',
      API_KEY: 'dev-api-key'
    };

    this.getSecretFn = async (key) => {
      return this.devSecrets[key] || process.env[key];
    };
  }

  /**
   * Get secret with caching and encryption
   */
  async getSecret(secretId, options = {}) {
    const {
      forceRefresh = false,
      decrypt = this.options.encryptionEnabled,
      validate = this.options.validateOnLoad
    } = options;

    // Check cache first
    const cacheKey = `secret:${secretId}`;
    if (!forceRefresh) {
      const cached = this.cache.get(cacheKey);
      if (cached) {
        this.logger.info('Cache hit for secret', { secretId });
        return cached;
      }
    }

    // Fetch from provider
    this.logger.info('Fetching secret from provider', { 
      secretId, 
      provider: this.options.provider 
    });

    try {
      const secretValue = await this.getSecretFn(secretId);

      // Validate secret
      if (validate) {
        this.validateSecret(secretId, secretValue);
      }

      // Decrypt if needed
      const processedValue = decrypt ? 
        this.decryptIfNeeded(secretValue) : 
        secretValue;

      // Cache the secret
      this.cache.put(cacheKey, processedValue, this.options.cacheDuration);

      // Audit log
      this.logger.audit('Secret accessed', {
        timestamp: new Date().toISOString(),
        secretId,
        action: 'read',
        provider: this.options.provider
      });

      return processedValue;

    } catch (error) {
      this.logger.error('Failed to fetch secret', {
        secretId,
        error: error.message,
        stack: error.stack
      });
      throw error;
    }
  }

  /**
   * Get multiple secrets at once
   */
  async getSecrets(secretIds, options = {}) {
    const secrets = {};

    // Fetch in parallel with rate limiting
    const promises = secretIds.map(async (secretId) => {
      try {
        secrets[secretId] = await this.getSecret(secretId, options);
      } catch (error) {
        secrets[secretId] = { error: error.message };
      }
    });

    await Promise.all(promises);
    return secrets;
  }

  /**
   * Validate secret meets security requirements
   */
   validateSecret(secretId, value) {
    // Check for placeholder/canary values
    if (typeof value === 'string') {
      const lowerValue = value.toLowerCase();
      const forbiddenPatterns = [
        'canary',
        'example',
        'placeholder',
        'changeme',
        'test',
        'password'
      ];

      const matches = forbiddenPatterns.filter(pattern => 
        lowerValue.includes(pattern)
      );

      if (matches.length > 0) {
        throw new Error(`Secret validation failed for ${secretId}: Contains forbidden patterns: ${matches.join(', ')}`);
      }
    }

    // Check minimum length for sensitive secrets
    if (secretId.toLowerCase().includes('secret') || secretId.toLowerCase().includes('key')) {
      if (typeof value === 'string' && value.length < 16) {
        throw new Error(`Secret validation failed for ${secretId}: Must be at least 16 characters`);
      }
    }

    return true;
  }

  /**
   * Decrypt secret if it's encrypted
   */
  decryptIfNeeded(value) {
    // Check if value is encrypted (starts with ENCRYPTED:)
    if (typeof value === 'string' && value.startsWith('ENCRYPTED:')) {
      const encrypted = value.substring(10); // Remove 'ENCRYPTED:' prefix
      const key = process.env.ENCRYPTION_KEY;

      if (!key) {
        throw new Error('ENCRYPTION_KEY environment variable required for decryption');
      }

      try {
        const decipher = crypto.createDecipheriv('aes-256-gcm', 
          crypto.scryptSync(key, 'salt', 32), 
          Buffer.alloc(16, 0) // IV
        );

        let decrypted = decipher.update(encrypted, 'hex', 'utf8');
        decrypted += decipher.final('utf8');

        return decrypted;
      } catch (error) {
        throw new Error(`Failed to decrypt secret: ${error.message}`);
      }
    }

    return value; // Already decrypted or doesn't need decryption
  }

  /**
   * Rotate a secret (admin function)
   */
  async rotateSecret(secretId) {
    try {
      this.logger.info('Rotating secret', { secretId });

      // Different providers have different rotation APIs
      switch (this.options.provider) {
        case 'aws':
          await this.provider.rotateSecret({ SecretId: secretId }).promise();
          break;
        case 'vault':
          await this.provider.write(`${secretId}/rotate`, {});
          break;
        case 'azure':
          // Azure doesn't have built-in rotation - need custom implementation
          await this.rotateAzureSecret(secretId);
          break;
        default:
          throw new Error(`Rotation not supported for provider: ${this.options.provider}`);
      }

      // Invalidate cache
      this.cache.del(`secret:${secretId}`);

      this.logger.audit('Secret rotated', {
        secretId,
        timestamp: new Date().toISOString(),
        action: 'rotate'
      });

      return true;

    } catch (error) {
      this.logger.error('Failed to rotate secret', {
        secretId,
        error: error.message
      });
      throw error;
    }
  }

  async rotateAzureSecret(secretId) {
    const newSecret = crypto.randomBytes(32).toString('hex');
    await this.provider.setSecret(secretId, newSecret);

    // Optional: Update the secret wherever it's used
    // This would be application-specific
  }

  /**
   * List all available secrets
   */
  async listSecrets() {
    try {
      switch (this.options.provider) {
        case 'aws':
          const data = await this.provider.listSecrets().promise();
          return data.SecretList.map(secret => ({
            name: secret.Name,
            description: secret.Description,
            lastChanged: secret.LastChangedDate,
            rotationEnabled: secret.RotationEnabled || false
          }));
        default:
          throw new Error(`Listing not supported for provider: ${this.options.provider}`);
      }
    } catch (error) {
      this.logger.error('Failed to list secrets', { error: error.message });
      throw error;
    }
  }

  /**
   * Initialize application with secrets
   */
  static async bootstrapApp() {
    const manager = new SecretsManager();

    // Load required secrets
    const requiredSecrets = [
      'DATABASE_URL',
      'JWT_SECRET',
      'API_KEYS',
      'ENCRYPTION_KEY'
    ];

    try {
      const secrets = await manager.getSecrets(requiredSecrets);

      // Set environment variables
      Object.entries(secrets).forEach(([key, value]) => {
        if (value && !value.error) {
          process.env[key] = value;
        }
      });

      // Validate all required secrets are present
      const missing = requiredSecrets.filter(key => !process.env[key]);
      if (missing.length > 0) {
        throw new Error(`Missing required secrets: ${missing.join(', ')}`);
      }

      const app = require('./app');
      return app;

    } catch (error) {
      console.error('❌ Failed to bootstrap application with secrets:', error.message);
      process.exit(1);
    }
  }
}

module.exports = SecretsManager;

#!/usr/bin/env node
/**
 * Secure Application Bootstrap
 * Proper secrets management with multiple provider support
 */

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// Environment validation
const ENV = process.env.NODE_ENV || 'development';
const IS_PROD = ENV === 'production';
const IS_DEV = ENV === 'development';
const IS_TEST = ENV === 'test';

// Security configuration
const SECURITY_CONFIG = {
  // Provider selection
  SECRETS_PROVIDER: process.env.SECRETS_PROVIDER || (IS_PROD ? 'aws' : 'local'),

  // Validation rules
  MIN_SECRET_LENGTH: 16,
  FORBIDDEN_PATTERNS: ['canary', 'example', 'placeholder', 'changeme', 'password'],

  // Cache settings
  CACHE_DURATION: IS_PROD ? 300000 : 60000, // 5 min prod, 1 min dev

  // Encryption
  ENCRYPTION_REQUIRED: IS_PROD,

  // Audit logging
  AUDIT_ENABLED: true,
  AUDIT_LOG_PATH: 'logs/secrets-audit.log'
};

/**
 * Security validation utilities
 */
class SecurityValidator {
  static validateEnvironment() {
    // Check for unsafe .env files in production
    if (IS_PROD) {
      const envFiles = ['.env', '.env.local', '.env.production'];
      envFiles.forEach(file => {
        if (fs.existsSync(file)) {
          console.error(`❌ CRITICAL: ${file} file found in production`);
          console.error('   Production must use secrets manager');
          process.exit(1);
        }
      });
    }

    // Validate environment variables
    const requiredEnv = IS_PROD ? [
      'NODE_ENV',
      'PORT',
      'SECRETS_PROVIDER'
    ] : ['NODE_ENV'];

    const missing = requiredEnv.filter(key => !process.env[key]);
    if (missing.length > 0) {
      console.error(`❌ Missing required environment variables: ${missing.join(', ')}`);
      process.exit(1);
    }

    return true;
  }

  static validateSecret(secretName, secretValue) {
    if (typeof secretValue !== 'string') {
      return true; // Non-string secrets might be objects
    }

    // Check for forbidden patterns
    const lowerValue = secretValue.toLowerCase();
    const forbidden = SECURITY_CONFIG.FORBIDDEN_PATTERNS.filter(pattern => 
      lowerValue.includes(pattern)
    );

    if (forbidden.length > 0) {
      console.warn(`⚠️ WARNING: Secret ${secretName} contains forbidden patterns: ${forbidden.join(', ')}`);

      if (IS_PROD) {
        console.error(`❌ Production secret ${secretName} contains placeholder values`);
        return false;
      }
    }

    // Check minimum length for sensitive secrets
    const sensitivePatterns = ['secret', 'key', 'token', 'password'];
    const isSensitive = sensitivePatterns.some(pattern => 
      secretName.toLowerCase().includes(pattern)
    );

    if (isSensitive && secretValue.length < SECURITY_CONFIG.MIN_SECRET_LENGTH) {
      console.error(`❌ Secret ${secretName} is too short (${secretValue.length} < ${SECURITY_CONFIG.MIN_SECRET_LENGTH})`);
      return false;
    }

    return true;
  }
}

/**
 * Secrets loader with provider abstraction
 */
class SecretsLoader {
  constructor() {
    this.provider = SECURITY_CONFIG.SECRETS_PROVIDER;
    this.secretsCache = new Map();
    this.loader = this.initializeLoader();
  }

  initializeLoader() {
    switch (this.provider) {
      case 'aws':
        return this.loadAWSSecrets();
      case 'vault':
        return this.loadVaultSecrets();
      case 'azure':
        return this.loadAzureSecrets();
      case 'local':
        return this.loadLocalSecrets();
      default:
        throw new Error(`Unknown secrets provider: ${this.provider}`);
    }
  }

  async loadAWSSecrets() {
    const AWS = require('aws-sdk');
    console.log('🔐 Using AWS Secrets Manager');

    const client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    return async (secretName) => {
      try {
        const data = await client.getSecretValue({ SecretId: secretName }).promise();
        const secret = data.SecretString ? JSON.parse(data.SecretString) : data.SecretBinary;

        // Cache for performance
        this.secretsCache.set(secretName, secret);
        return secret;
      } catch (error) {
        console.error(`❌ Failed to load secret ${secretName}:`, error.message);
        throw error;
      }
    };
  }

  async loadVaultSecrets() {
    const NodeVault = require('node-vault');
    console.log('🔐 Using Hashicorp Vault');

    const vault = NodeVault({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN
    });

    return async (path) => {
      try {
        const secret = await vault.read(path);
        this.secretsCache.set(path, secret.data);
        return secret.data;
      } catch (error) {
        console.error(`❌ Failed to load secret ${path}:`, error.message);
        throw error;
      }
    };
  }

  async loadLocalSecrets() {
    console.warn('⚠️ WARNING: Using local secrets provider - FOR DEVELOPMENT ONLY');

    if (IS_PROD) {
      throw new Error('Local secrets provider not allowed in production');
    }

    // Load from environment or .env file
    require('dotenv').config();

    return async (key) => {
      // Check cache
      if (this.secretsCache.has(key)) {
        return this.secretsCache.get(key);
      }

      // Get from environment
      const value = process.env[key];

      if (!value) {
        console.warn(`⚠️ Secret ${key} not found in local environment`);
        return null;
      }

      // Validate local secret
      if (!SecurityValidator.validateSecret(key, value)) {
        console.warn(`⚠️ Invalid secret detected: ${key}`);
      }

      this.secretsCache.set(key, value);
      return value;
    };
  }

  async loadAzureSecrets() {
    const { SecretClient } = require('@azure/keyvault-secrets');
    const { DefaultAzureCredential } = require('@azure/identity');

    console.log('🔐 Using Azure Key Vault');

    const credential = new DefaultAzureCredential();
    const client = new SecretClient(
      process.env.AZURE_KEY_VAULT_URL,
      credential
    );

    return async (name) => {
      try {
        const secret = await client.getSecret(name);
        this.secretsCache.set(name, secret.value);
        return secret.value;
      } catch (error) {
        console.error(`❌ Failed to load secret ${name}:`, error.message);
        throw error;
      }
    };
  }

  async loadSecret(secretName) {
    // Check cache first
    if (this.secretsCache.has(secretName)) {
      return this.secretsCache.get(secretName);
    }

    // Load from provider
    const value = await this.loader(secretName);

    // Validate secret
    if (value && !SecurityValidator.validateSecret(secretName, value)) {
      throw new Error(`Invalid secret: ${secretName}`);
    }

    return value;
  }

  async loadAllSecrets(secretNames) {
    const secrets = {};
    const promises = secretNames.map(async (name) => {
      try {
        secrets[name] = await this.loadSecret(name);
      } catch (error) {
        console.error(`❌ Failed to load secret ${name}:`, error.message);
        secrets[name] = null;
      }
    });

    await Promise.all(promises);
    return secrets;
  }
}

/**
 * Application bootstrap
 */
async function bootstrapApplication() {
  console.log(`🚀 Bootstrapping application in ${ENV} environment`);
  console.log(`🔐 Secrets provider: ${SECURITY_CONFIG.SECRETS_PROVIDER}`);

  // Step 1: Environment validation
  console.log('📋 Validating environment...');
  SecurityValidator.validateEnvironment();

  // Step 2: Load secrets
  console.log('🔐 Loading secrets...');
  const secretsLoader = new SecretsLoader();

  // Define required secrets based on environment
  const requiredSecrets = IS_PROD ? [
    'DATABASE_URL',
    'JWT_SECRET',
    'API_KEYS',
    'ENCRYPTION_KEY',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY'
  ] : [
    'DATABASE_URL',
    'JWT_SECRET'
  ];

  const loadedSecrets = await secretsLoader.loadAllSecrets(requiredSecrets);

  // Step 3: Set environment variables
  console.log('⚙️ Setting environment variables...');
  Object.entries(loadedSecrets).forEach(([key, value]) => {
    if (value) {
      process.env[key] = value;
      console.log(`   ${key}: ${IS_PROD ? '••••••' : value.substring(0, 10)}...`);
    } else {
      console.warn(`   ⚠️ ${key}: NOT LOADED`);
    }
  });

  // Step 4: Validate all secrets are present
  const missingSecrets = requiredSecrets.filter(key => !process.env[key]);
  if (missingSecrets.length > 0 && IS_PROD) {
    console.error(`❌ Missing required secrets: ${missingSecrets.join(', ')}`);
    process.exit(1);
  }

  // Step 5: Load application
  console.log('📦 Loading application...');
  const express = require('express');
  const helmet = require('helmet');
  const cors = require('cors');
  const rateLimit = require('express-rate-limit');

  const app = express();

  // Security middleware
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        scriptSrc: ["'self'"],
        imgSrc: ["'self'", "data:", "https:"],
      },
    }
  }));

  app.use(cors({
    origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
    credentials: true
  }));

  // Rate limiting
  const limiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: IS_PROD ? 100 : 1000,
    message: 'Too many requests from this IP'
  });
  app.use('/api', limiter);

  // Health endpoint with secrets status
  app.get('/health', (req, res) => {
    res.json({
      status: 'healthy',
      environment: ENV,
      timestamp: new Date().toISOString(),
      secrets: {
        provider: SECURITY_CONFIG.SECRETS_PROVIDER,
        loaded: Object.keys(loadedSecrets).filter(k => loadedSecrets[k]),
        missing: Object.keys(loadedSecrets).filter(k => !loadedSecrets[k])
      }
    });
  });

  // Secure routes
  app.get('/secure/users', (req, res) => {
    // Verify API key from secrets
    const apiKey = req.headers['x-api-key'];
    const expectedKey = process.env.API_KEYS || process.env.API_KEY;

    if (!expectedKey || apiKey !== expectedKey) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  });

  // Error handling
  app.use((err, req, res, next) => {
    console.error('Application error:', err.stack);

    // Don't leak secrets in errors
    const errorResponse = {
      error: 'Internal Server Error'
    };

    if (IS_DEV) {
      errorResponse.message = err.message;
      // Only include stack trace in development
      errorResponse.stack = err.stack;
    }

    res.status(500).json(errorResponse);
  });

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`✅ Server running on port ${PORT}`);
    console.log(`✅ Environment: ${ENV}`);
    console.log(`✅ Secrets provider: ${SECURITY_CONFIG.SECRETS_PROVIDER}`);
    console.log(`✅ Secrets loaded: ${requiredSecrets.filter(k => process.env[k]).length}/${requiredSecrets.length}`);

    if (IS_PROD) {
      console.log('🔒 PRODUCTION MODE: All security features enabled');
    }
  });

  return app;
}

